+Below is a complete self-contained React component (in JavaScript) that implements Dijkstra’s algorithm and displays the results in a polished, modern UI using Tailwind CSS. In this component you can select the source vertex from a dropdown, click a button to compute the shortest paths, and then see the results (distance and actual path) in a styled table.
+
+Explanation of the solution:
+
+1. We define a fixed graph using an adjacency matrix.
+2. The dijkstra() function implements the algorithm and returns both the distances and parent arrays.
+3. The buildPath() helper function recursively builds a string representing the shortest path from the source to any vertex.
+4. The UI uses React state to capture the selected source vertex and the computed result. Tailwind classes are used to create a modern, responsive layout.
+5. The component is exported as the default export so it can run independently in a sandbox environment.
+
+Below is the complete code in one file:
+
+```jsx
+import React, { useState } from 'react';
+
+const DijkstraVisualizer = () => {
+  // Define a fixed graph as an adjacency matrix.
+  const graph = [
+    [0, 4, 0, 0, 0, 0, 0, 8, 0],
+    [4, 0, 8, 0, 0, 0, 0, 11, 0],
+    [0, 8, 0, 7, 0, 4, 0, 0, 2],
+    [0, 0, 7, 0, 9, 14, 0, 0, 0],
+    [0, 0, 0, 9, 0, 10, 0, 0, 0],
+    [0, 0, 4, 14, 10, 0, 2, 0, 0],
+    [0, 0, 0, 0, 0, 2, 0, 1, 6],
+    [8, 11, 0, 0, 0, 0, 1, 0, 7],
+    [0, 0, 2, 0, 0, 0, 6, 7, 0]
+  ];
+  const V = graph.length;
+
+  // Dijkstra's algorithm function.
+  function dijkstra(graph, src) {
+    const dist = new Array(V).fill(Infinity);
+    const sptSet = new Array(V).fill(false);
+    const parent = new Array(V).fill(-1);
+
+    // Distance to the source is 0.
+    dist[src] = 0;
+
+    // Process all vertices.
+    for (let count = 0; count < V - 1; count++) {
+      let u = -1;
+      let minDist = Infinity;
+      // Find the vertex with the minimum distance value.
+      for (let i = 0; i < V; i++) {
+        if (!sptSet[i] && dist[i] < minDist) {
+          minDist = dist[i];
+          u = i;
+        }
+      }
+      if (u === -1) break; // In case of disconnected components.
+
+      sptSet[u] = true;
+
+      // Update distances of the adjacent vertices.
+      for (let v = 0; v < V; v++) {
+        if (!sptSet[v] && graph[u][v] && dist[u] !== Infinity && dist[u] + graph[u][v] < dist[v]) {
+          dist[v] = dist[u] + graph[u][v];
+          parent[v] = u;
+        }
+      }
+    }
+    return { dist, parent };
+  }
+
+  // Helper function to recursively build the path from source to vertex j.
+  function buildPath(parent, j) {
+    if (parent[j] === -1) return `${j}`;
+    return buildPath(parent, parent[j]) + " → " + j;
+  }
+
+  // React state for source vertex and computed result.
+  const [source, setSource] = useState(0);
+  const [result, setResult] = useState(null);
+
+  const handleCompute = () => {
+    const res = dijkstra(graph, Number(source));
+    setResult(res);
+  };
+
+  return (
+    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
+      <div className="bg-white shadow-lg rounded-lg p-6 w-full max-w-2xl">
+        <h1 className="text-2xl font-bold mb-4 text-center text-blue-600">
+          Dijkstra's Algorithm Visualizer
+        </h1>
+        <div className="mb-4">
+          <label htmlFor="source" className="block text-gray-700 font-medium mb-2">
+            Select Source Vertex:
+          </label>
+          <select
+            id="source"
+            className="w-full border border-gray-300 rounded p-2"
+            value={source}
+            onChange={(e) => { setSource(e.target.value); setResult(null); }}
+          >
+            {graph.map((_, index) => (
+              <option key={index} value={index}>
+                Vertex {index}
+              </option>
+            ))}
+          </select>
+        </div>
+        <button
+          onClick={handleCompute}
+          className="w-full bg-blue-500 hover:bg-blue-600 text-white font-medium py-2 px-4 rounded mb-6"
+        >
+          Compute Shortest Paths
+        </button>
+        {result && (
+          <div>
+            <h2 className="text-xl font-bold mb-4 text-blue-500">
+              Results from Source Vertex {source}
+            </h2>
+            <table className="min-w-full bg-white border">
+              <thead>
+                <tr>
+                  <th className="py-2 px-4 border-b text-left">Vertex</th>
+                  <th className="py-2 px-4 border-b text-left">Distance</th>
+                  <th className="py-2 px-4 border-b text-left">Path</th>
+                </tr>
+              </thead>
+              <tbody>
+                {result.dist.map((d, index) => (
+                  <tr key={index} className="hover:bg-gray-50">
+                    <td className="py-2 px-4 border-b">{index}</td>
+                    <td className="py-2 px-4 border-b">{d === Infinity ? "∞" : d}</td>
+                    <td className="py-2 px-4 border-b">
+                      {d === Infinity ? "No Path" : buildPath(result.parent, index)}
+                    </td>
+                  </tr>
+                ))}
+              </tbody>
+            </table>
+          </div>
+        )}
+      </div>
+    </div>
+  );
+};
+
+export default DijkstraVisualizer;
+```
+
+To run this component in a sandbox environment (for example, using CodeSandbox or a similar React playground), simply paste the code into a file (e.g., DijkstraVisualizer.jsx) and import it into your application. Tailwind is used for styling, so ensure your environment is set up with TailwindCSS. If not, you can also replace Tailwind classes with your preferred styles.
+
+This solution provides a polished and interactive UI for exploring Dijkstra's algorithm. Enjoy experimenting with it!
