+```tsx
+import React, { useState, useEffect } from 'react';
+import axios from 'axios';
+
+// Define TypeScript interfaces for type safety
+interface WebsiteStatus {
+  url: string;
+  status: number | string;
+  responseTime?: number;
+  timestamp: string;
+  isUp: boolean;
+  error?: string;
+}
+
+const WebsiteMonitorDashboard: React.FC = () => {
+  // State management
+  const [websites, setWebsites] = useState<string[]>([
+    'https://www.google.com',
+    'https://www.github.com',
+    'https://www.stackoverflow.com'
+  ]);
+  const [newWebsite, setNewWebsite] = useState<string>('');
+  const [statusLog, setStatusLog] = useState<WebsiteStatus[]>([]);
+  const [isMonitoring, setIsMonitoring] = useState<boolean>(false);
+
+  // Website monitoring logic
+  const checkWebsite = async (url: string): Promise<WebsiteStatus> => {
+    try {
+      const startTime = Date.now();
+      const response = await axios.get(url, { 
+        timeout: 5000,
+        validateStatus: () => true 
+      });
+
+      const endTime = Date.now();
+      const responseTime = endTime - startTime;
+
+      return {
+        url,
+        status: response.status,
+        responseTime,
+        timestamp: new Date().toISOString(),
+        isUp: response.status >= 200 && response.status < 400
+      };
+    } catch (error) {
+      return {
+        url,
+        status: 'ERROR',
+        error: (error as Error).message,
+        timestamp: new Date().toISOString(),
+        isUp: false
+      };
+    }
+  };
+
+  // Monitoring function
+  const monitorWebsites = async () => {
+    const checks = websites.map(async (website) => {
+      const result = await checkWebsite(website);
+      setStatusLog(prevLog => [result, ...prevLog].slice(0, 20));
+      return result;
+    });
+
+    await Promise.all(checks);
+  };
+
+  // Start/Stop monitoring
+  const toggleMonitoring = () => {
+    setIsMonitoring(!isMonitoring);
+  };
+
+  // Add new website to monitoring list
+  const addWebsite = () => {
+    if (newWebsite && !websites.includes(newWebsite)) {
+      setWebsites([...websites, newWebsite]);
+      setNewWebsite('');
+    }
+  };
+
+  // Remove website from monitoring list
+  const removeWebsite = (urlToRemove: string) => {
+    setWebsites(websites.filter(url => url !== urlToRemove));
+  };
+
+  // Periodic monitoring effect
+  useEffect(() => {
+    let intervalId: NodeJS.Timeout;
+    
+    if (isMonitoring) {
+      // Initial check
+      monitorWebsites();
+      
+      // Periodic checks every 30 seconds
+      intervalId = setInterval(monitorWebsites, 30000);
+    }
+
+    // Cleanup interval on component unmount or monitoring stop
+    return () => {
+      if (intervalId) clearInterval(intervalId);
+    };
+  }, [isMonitoring, websites]);
+
+  // Render status color based on website status
+  const getStatusColor = (isUp: boolean) => 
+    isUp ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800';
+
+  return (
+    <div className="min-h-screen bg-gray-100 p-6">
+      <div className="max-w-4xl mx-auto bg-white shadow-lg rounded-lg p-6">
+        <h1 className="text-3xl font-bold mb-6 text-center text-blue-600">
+          Website Monitoring Dashboard
+        </h1>
+
+        {/* Website Input Section */}
+        <div className="flex mb-6">
+          <input 
+            type="text" 
+            value={newWebsite}
+            onChange={(e) => setNewWebsite(e.target.value)}
+            placeholder="Enter website URL"
+            className="flex-grow p-2 border rounded-l-lg"
+          />
+          <button 
+            onClick={addWebsite}
+            className="bg-blue-500 text-white px-4 py-2 rounded-r-lg hover:bg-blue-600"
+          >
+            Add Website
+          </button>
+        </div>
+
+        {/* Monitoring Control */}
+        <div className="flex justify-center mb-6">
+          <button 
+            onClick={toggleMonitoring}
+            className={`px-6 py-2 rounded-lg text-white ${
+              isMonitoring 
+                ? 'bg-red-500 hover:bg-red-600' 
+                : 'bg-green-500 hover:bg-green-600'
+            }`}
+          >
+            {isMonitoring ? 'Stop Monitoring' : 'Start Monitoring'}
+          </button>
+        </div>
+
+        {/* Monitored Websites List */}
+        <div className="mb-6">
+          <h2 className="text-xl font-semibold mb-3">Monitored Websites</h2>
+          <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
+            {websites.map(url => (
+              <div 
+                key={url} 
+                className="flex justify-between items-center bg-gray-100 p-2 rounded"
+              >
+                <span>{url}</span>
+                <button 
+                  onClick={() => removeWebsite(url)}
+                  className="text-red-500 hover:text-red-700"
+                >
+                  ✕
+                </button>
+              </div>
+            ))}
+          </div>
+        </div>
+
+        {/* Status Log */}
+        <div>
+          <h2 className="text-xl font-semibold mb-3">Status Log</h2>
+          <div className="max-h-80 overflow-y-auto">
+            {statusLog.map((log, index) => (
+              <div 
+                key={index} 
+                className={`p-3 mb-2 rounded ${getStatusColor(log.isUp)}`}
+              >
+                <div className="flex justify-between">
+                  <span className="font-semibold">{log.url}</span>
+                  <span>{new Date(log.timestamp).toLocaleString()}</span>
+                </div>
+                <div>
