+```javascript
+const axios = require('axios');
+const fs = require('fs');
+const path = require('path');
+const moment = require('moment');
+
+class WebsiteMonitor {
+    constructor(config, io) {
+        this.config = config;
+        this.io = io;
+        this.statusHistory = new Map();
+        this.latestStatus = new Map();
+    }
+
+    async checkWebsite(website) {
+        // Previous checkWebsite implementation with some additions
+        const result = await super.checkWebsite(website);
+        
+        // Store status history
+        if (!this.statusHistory.has(website)) {
+            this.statusHistory.set(website, []);
+        }
+        const history = this.statusHistory.get(website);
+        history.push({ timestamp: new Date(), ...result });
+        if (history.length > 100) history.shift(); // Keep last 100 checks
+
+        // Update latest status
+        this.latestStatus.set(website, {
+            timestamp: new Date(),
+            ...result
+        });
+
+        // Emit update via Socket.IO
+        this.io.emit('statusUpdate', {
+            website,
+            status: result
+        });
+
+        return result;
+    }
+
+    getLatestStatus() {
+        return Object.fromEntries(this.latestStatus);
+    }
+
+    getHistory() {
+        return Object.fromEntries(this.statusHistory);
+    }
+}
+
+module.exports = WebsiteMonitor;
+```
