+```javascript
+const socket = io();
+let responseTimeChart;
+
+// Initialize the dashboard
+async function initDashboard() {
+    // Fetch initial data
+    const response = await fetch('/api/status');
+    const statusData = await response.json();
+    updateStatusCards(statusData);
+
+    // Initialize chart
+    initChart();
+
+    // Listen for real-time updates
+    socket.on('statusUpdate', (data) => {
+        updateStatusCard(data.website, data.status);
+        updateChart(data.website, data.status);
+    });
+}
+
+function updateStatusCards(statusData) {
+    const container = document.getElementById('status-cards');
+    container.innerHTML = '';
+
+    Object.entries(statusData).forEach(([website, status]) => {
+        container.appendChild(createStatusCard(website, status));
+    });
+}
+
+function createStatusCard(website, status) {
+    const card = document.createElement('div');
+    card.className = 'status-card';
+    card.innerHTML = `
+        <h3 class="text-lg font-semibold">${website}</h3>
+        <div class="status ${status.status === 'up' ? 'status-up' : 'status-down'}">
+            ${status.status.toUpperCase()}
+        </div>
+        ${status.responseTime ? `
+            <div class="response-time">
+                Response Time: ${status.responseTime}ms
+            </div>
+        ` : ''}
+        <div class="text-sm text-gray-500">
+            Last checked: ${moment(status.timestamp).fromNow()}
+        </div>
+    `;
+    return card;
+}
+
+function initChart() {
+    const ctx = document.getElementById('responseTimeChart').getContext('2d');
+    responseTimeChart = new Chart(ctx, {
+        type: 'line',
+        data: {
+            labels: [],
+            datasets: []
+        },
+        options: {
+            responsive: true,
+            scales: {
+                y: {
+                    beginAtZero: true,
+                    title: {
+                        display: true,
+                        text: 'Response Time (ms)'
+                    }
+                }
+            }
+        }
+    });
+}
+
+function updateChart(website, status) {
+    // Update chart with new data
+    const dataset = responseTimeChart.data.datasets.find(ds => ds.label === website);
+    if (dataset) {
+        dataset.data.push(status.responseTime);
+        if (dataset.data.length > 20) dataset.data.shift();
+    } else {
+        responseTimeChart.data.datasets.push({
+            label: website,
+            data: [status.responseTime],
+            borderColor: getRandomColor(),
+            fill: false
+        });
+    }
+    responseTimeChart.update();
+}
+
+function getRandomColor() {
+    const letters = '0123456789ABCDEF';
+    let color = '#';
+    for (let i = 0; i < 6; i++) {
+        color += letters[Math.floor(Math.random() * 16)];
+    }
+    return color;
+}
+
+// Initialize the dashboard when the page loads
+document.addEventListener('DOMContentLoaded', initDashboard);
+```
