+      </div>
+      <div className="flex space-x-2">
+        <button
+          onClick={() => onEdit(post)}
+          className="bg-blue-500 text-white px-3 py-1 rounded-md hover:bg-blue-600"
+        >
+          Edit
+        </button>
+        <button
+          onClick={() => onDelete(post.id)}
+          className="bg-red-500 text-white px-3 py-1 rounded-md hover:bg-red-600"
+        >
+          Delete
+        </button>
+      </div>
+      <div className="mt-6">
+        <h3 className="text-xl font-bold">Comments</h3>
+        <ul className="space-y-2 mt-2">
+          {post.comments && post.comments.length > 0 ? (
+            post.comments.map((comment) => (
+              <li key={comment.id} className="p-2 bg-white border rounded-md">
+                <ReactMarkdown>{comment.text}</ReactMarkdown>
+              </li>
+            ))
+          ) : (
+            <li className="text-gray-600">No comments yet.</li>
+          )}
+        </ul>
+        <CommentForm onAddComment={onAddComment} />
+      </div>
+    </div>
+  );
+};
+
+const PostList = ({ posts, onSelectPost, onAddNewPost }) => {
+  return (
+    <div>
+      <div className="flex justify-between items-center mb-4">
+        <h1 className="text-3xl font-bold">Blog Posts</h1>
+        <button
+          onClick={onAddNewPost}
+          className="bg-green-500 text-white px-4 py-2 rounded-md hover:bg-green-600"
+        >
+          New Post
+        </button>
+      </div>
+      {posts.length > 0 ? (
+        <ul className="space-y-4">
+          {posts.map((post) => (
+            <li
+              key={post.id}
+              onClick={() => onSelectPost(post)}
+              className="p-4 bg-white rounded-md shadow hover:bg-gray-100 cursor-pointer"
+            >
+              <h2 className="text-xl font-bold">{post.title}</h2>
+              <div className="text-gray-700 mt-2 line-clamp-3">
+                <ReactMarkdown>
+                  {post.content.length > 100
+                    ? post.content.slice(0, 100) + "..."
+                    : post.content}
+                </ReactMarkdown>
+              </div>
+            </li>
+          ))}
+        </ul>
+      ) : (
+        <p className="text-gray-600">No posts available.</p>
+      )}
+    </div>
+  );
+};
+
+const App = () => {
+  const [posts, setPosts] = useState(initialPosts);
+  const [view, setView] = useState("list"); // list, view, edit, new
+  const [currentPost, setCurrentPost] = useState(null);
+
+  // Create or update a post
+  const handleSavePost = (post) => {
+    if (post.id) {
+      // edit existing
+      setPosts((prev) =>
+        prev.map((p) => (p.id === post.id ? { ...p, title: post.title, content: post.content } : p))
+      );
+    } else {
+      // create new
+      const newPost = {
+        ...post,
+        id: Date.now(),
+        comments: []
+      };
+      setPosts((prev) => [newPost, ...prev]);
+    }
+    setView("list");
+    setCurrentPost(null);
+  };
+
+  // Delete a post
+  const handleDeletePost = (id) => {
+    setPosts((prev) => prev.filter((p) => p.id !== id));
+    setView("list");
+    setCurrentPost(null);
+  };
+
+  // Edit a post
+  const handleEditPost = (post) => {
+    setCurrentPost(post);
+    setView("edit");
+  };
+
+  // View a post in detail
+  const handleSelectPost = (post) => {
+    setCurrentPost(post);
+    setView("view");
+  };
+
+  // Add comment to current post
+  const handleAddComment = (text) => {
+    const comment = { id: Date.now(), text };
+    setPosts((prev) =>
+      prev.map((p) =>
+        p.id === currentPost.id ? { ...p, comments: [...p.comments, comment] } : p
+      )
+    );
+    setCurrentPost((prev) => ({ ...prev, comments: [...prev.comments, comment] }));
+  };
+
+  return (
+    <div className="min-h-screen bg-gray-100 p-4">
+      <div className="max-w-3xl mx-auto">
+        {view === "list" && (
+          <PostList
+            posts={posts}
+            onSelectPost={handleSelectPost}
+            onAddNewPost={() => {
+              setCurrentPost(null);
+              setView("new");
+            }}
+          />
+        )}
+        {(view === "new" || view === "edit") && (
+          <PostForm
+            post={view === "edit" ? currentPost : null}
+            onSave={handleSavePost}
+            onCancel={() => {
+              setView("list");
+              setCurrentPost(null);
+            }}
+          />
+        )}
+        {view === "view" && currentPost && (
+          <PostDetail
+            post={currentPost}
+            onBack={() => {
+              setView("list");
+              setCurrentPost(null);
+            }}
+            onEdit={handleEditPost}
+            onDelete={handleDeletePost}
+            onAddComment={handleAddComment}
+          />
+        )}
+      </div>
+    </div>
+  );
+};
+
+export default App;
+```
+
+Explanation:
+
+1. We import and use ReactMarkdown to render Markdown content for both posts and comments.
+2. The PostForm now includes a toggle button ("Preview"/"Edit") that allows users to switch between a Markdown-rendered preview and a textarea for editing the content.
+3. Similarly, CommentForm provides a toggle to preview Markdown rendering of the comment before submission.
+4. PostDetail uses ReactMarkdown to render the Markdown formatted content and comments.
+5. Posts are listed with a preview snippet rendered in Markdown.
+
+This enhanced blog platform now supports Markdown formatting for both posts and comments. Enjoy testing your improved Markdown‑enabled blog!
