+              onChange={(e) => setNewQuestion(e.target.value)}
+              className="w-full border border-gray-300 rounded px-4 py-2"
+            />
+          </div>
+          <div className="mb-4">
+            {newOptions.map((option, index) => (
+              <div key={index} className="mb-2">
