+          {leaderboard.map((entry, index) => (
+            <li key={index} className="flex justify-between py-2 border-b">
+              <span>{entry.username}</span>
+              <span>{entry.score} pts</span>
+            </li>
+          ))}
+        </ul>
+      </div>
+    </div>
+  );
+};
+
+export default QuizApp;
+```
+
