+Below is a single-pass JavaScript solution that decides if an array can become non-decreasing (nums[i] ≤ nums[i+1]) with at most one modification. The program logs sample test cases at the end.
+
+Explanation of the approach:
+1. Traverse the array once (single pass).
+2. Keep track of violations where nums[i] > nums[i+1].
+3. If there is more than one violation, return false.
+4. If there's exactly one violation, adjust either nums[i] or nums[i+1] (conceptually) in a safe way. Specifically:
+   - If possible, reduce nums[i] (e.g., when i == 0 or nums[i-1] ≤ nums[i+1]). Otherwise, raise nums[i+1].
+5. Return true if at most one fix is needed.
+
+```javascript
+// A single-pass function to check if at most one modification
+// can make the array non-decreasing.
+function canMakeNonDecreasing(nums) {
+  let countViolations = 0;
+  
+  for (let i = 0; i < nums.length - 1; i++) {
+    if (nums[i] > nums[i + 1]) {
+      // Found a violation
+      countViolations++;
+      if (countViolations > 1) {
+        return false;
+      }
+      
+      // If we can't safely lower nums[i], we'll consider raising nums[i+1]
+      if (i > 0 && nums[i - 1] > nums[i + 1]) {
+        // We would, in theory, adjust nums[i+1] instead
+        nums[i + 1] = nums[i];
+      }
+    }
+  }
+  return true;
+}
+
+// Test the function with various arrays:
+const testCases = [
+  { nums: [4, 2, 3], expected: true },
+  { nums: [4, 2, 1], expected: false },
+  { nums: [1, 5, 4, 6], expected: true },
+  { nums: [10, 5, 7], expected: true },
+  { nums: [1, 2, 3], expected: true },
+  { nums: [3, 4, 2, 3], expected: false },
+];
+
+testCases.forEach(({ nums, expected }) => {
+  const result = canMakeNonDecreasing([...nums]); // pass a copy
+  console.log(`nums = [${nums.join(", ")}], result: ${result}, expected: ${expected}`);
+});
+```
