+    ];
+
+    // Draw the evolving organism
+    const drawOrganism = () => {
+      const centerX = canvas.width / 2;
+      const centerY = canvas.height / 2;
+
+      ctx.save();
+      ctx.translate(centerX, centerY);
+
+      // Base organism core
+      const basePulse = Math.sin(organism.seed) * 50;
+      const baseSize = 100 + basePulse;
+
+      // Gradient for depth
+      const gradient = ctx.createRadialGradient(
+        0, 0, 10, 
+        0, 0, baseSize
+      );
+      gradient.addColorStop(0, colorPalette[Math.floor(organism.colorShift % colorPalette.length)]);
+      gradient.addColorStop(1, 'rgba(0,0,0,0.1)');
+
+      // Main body
+      ctx.beginPath();
+      ctx.fillStyle = gradient;
+      ctx.shadowBlur = 20;
+      ctx.shadowColor = 'rgba(0,0,0,0.3)';
+
+      // Organic, pulsating shape
+      for (let i = 0; i < 360; i += 10) {
+        const angle = i * Math.PI / 180;
+        const radiusVariation = Math.sin(angle * organism.complexity + organism.seed) * 30;
+        const radius = baseSize + radiusVariation;
+
+        const x = Math.cos(angle) * radius;
+        const y = Math.sin(angle) * radius;
+
+        if (i === 0) {
+          ctx.moveTo(x, y);
+        } else {
+          ctx.lineTo(x, y);
+        }
+      }
+      ctx.closePath();
+      ctx.fill();
+
+      // Tentacle-like extensions
+      for (let i = 0; i < organism.tentacleCount; i++) {
+        ctx.save();
+        ctx.rotate((i / organism.tentacleCount) * Math.PI * 2 + organism.seed);
+        
+        ctx.beginPath();
+        ctx.moveTo(baseSize, 0);
+        
+        // Wavy, organic tentacle movement
+        for (let j = 0; j < 3; j++) {
+          const cp1x = baseSize + 50 + pseudoRandom(organism.seed + j) * 50;
+          const cp1y = pseudoRandom(organism.seed * j) * 30;
+          const cp2x = baseSize + 100 + pseudoRandom(organism.seed + j * 2) * 50;
+          const cp2y = pseudoRandom(organism.seed * j * 2) * -30;
+          const endX = baseSize + 150;
+          const endY = 0;
+
+          ctx.bezierCurveTo(cp1x, cp1y, cp2x, cp2y, endX, endY);
+        }
+
+        ctx.strokeStyle = colorPalette[Math.floor((organism.colorShift + i) % colorPalette.length)];
+        ctx.lineWidth = 3;
+        ctx.stroke();
+
+        ctx.restore();
+      }
+
+      ctx.restore();
+    };
+
+    // Draw and update
+    drawOrganism();
+
+    // Evolve the organism
+    const evolveOrganism = () => {
+      setOrganism(prev => ({
+        seed: prev.seed + 0.05,
+        complexity: 1 + Math.abs(Math.sin(prev.seed) * 2),
+        pulseRate: 0.5 + Math.sin(prev.seed) * 0.2,
+        colorShift: prev.colorShift + 0.1,
+        tentacleCount: 6 + Math.floor(Math.abs(Math.sin(prev.seed) * 3))
+      }));
+    };
+
+    // Animation loop
+    const animationFrame = requestAnimationFrame(evolveOrganism);
+
+    return () => {
+      cancelAnimationFrame(animationFrame);
+    };
+  }, [organism]);
+
+  return (
+    <div className="fixed inset-0 bg-black overflow-hidden">
+      <canvas 
+        ref={canvasRef} 
+        className="absolute top-0 left-0 w-full h-full"
+      />
+    </div>
+  );
+};
+
+export default GenerativeOrganism;
+```
