+        }
+        .image-gallery {
+            display: flex;
+            flex-wrap: wrap;
+            gap: 10px;
+            margin: 10px 0;
+        }
+        .test-image {
+            width: 150px;
+            height: 150px;
+            cursor: pointer;
+            border-radius: 4px;
+            border: 2px solid transparent;
+        }
+        .test-image:hover {
+            border-color: #4CAF50;
+        }
+        textarea {
+            width: 100%;
+            padding: 10px;
+            margin: 10px 0;
+            border-radius: 4px;
+            border: 1px solid #ddd;
+        }
+    </style>
+</head>
+<body>
+    <h1>Steganography Tool</h1>
+    
+    <div class="container">
+        <h2>Select Test Image</h2>
+        <div class="image-gallery" id="imageGallery"></div>
+    </div>
+
+    <div class="container">
+        <h2>Encode Message</h2>
+        <textarea id="messageInput" rows="4" placeholder="Enter your secret message"></textarea>
+        <button onclick="encodeMessage()">Encode</button>
+        <div>
+            <img id="preview" class="preview">
+        </div>
+    </div>
+
+    <div class="container">
+        <h2>Decode Message</h2>
+        <button onclick="decodeMessage()">Decode</button>
+        <div>
+            <textarea id="decodedMessage" rows="4" readonly></textarea>
+        </div>
+    </div>
+
+<script>
+// Global variables to store the current image
+let currentImage = null;
+
+// Generate multiple test images
+function generateTestImages() {
+    const gallery = document.getElementById('imageGallery');
+    const patterns = [
+        'gradient',
+        'circles',
+        'squares',
+        'triangles',
+        'stripes',
+        'dots'
+    ];
+
+    patterns.forEach((pattern, index) => {
+        const canvas = document.createElement('canvas');
+        canvas.width = 150;
+        canvas.height = 150;
+        const ctx = canvas.getContext('2d');
+
+        switch(pattern) {
+            case 'gradient':
+                const gradient = ctx.createLinearGradient(0, 0, 150, 150);
+                gradient.addColorStop(0, '#ff6b6b');
+                gradient.addColorStop(1, '#4ecdc4');
+                ctx.fillStyle = gradient;
+                ctx.fillRect(0, 0, 150, 150);
+                break;
+
+            case 'circles':
+                ctx.fillStyle = '#6c5ce7';
+                ctx.fillRect(0, 0, 150, 150);
+                for(let i = 0; i < 5; i++) {
+                    ctx.beginPath();
+                    ctx.arc(75, 75, 60 - (i * 12), 0, Math.PI * 2);
+                    ctx.fillStyle = i % 2 === 0 ? '#a8e6cf' : '#dcedc1';
+                    ctx.fill();
+                }
+                break;
+
+            case 'squares':
+                for(let i = 0; i < 6; i++) {
+                    for(let j = 0; j < 6; j++) {
+                        ctx.fillStyle = `hsl(${(i+j) * 30}, 70%, 60%)`;
+                        ctx.fillRect(i*25, j*25, 25, 25);
+                    }
+                }
+                break;
+
+            case 'triangles':
+                ctx.fillStyle = '#ffd3b6';
+                ctx.fillRect(0, 0, 150, 150);
+                for(let i = 0; i < 4; i++) {
+                    ctx.beginPath();
+                    ctx.moveTo(75, 20 + (i * 30));
+                    ctx.lineTo(130 - (i * 20), 130 - (i * 20));
+                    ctx.lineTo(20 + (i * 20), 130 - (i * 20));
+                    ctx.fillStyle = `hsl(${i * 60}, 70%, 60%)`;
+                    ctx.fill();
+                }
+                break;
+
+            case 'stripes':
+                for(let i = 0; i < 10; i++) {
+                    ctx.fillStyle = i % 2 === 0 ? '#ff9a9e' : '#fad0c4';
+                    ctx.fillRect(0, i * 15, 150, 15);
+                }
+                break;
+
+            case 'dots':
+                ctx.fillStyle = '#a8e6cf';
+                ctx.fillRect(0, 0, 150, 150);
+                for(let i = 0; i < 6; i++) {
+                    for(let j = 0; j < 6; j++) {
+                        ctx.beginPath();
+                        ctx.arc(25 + i*25, 25 + j*25, 8, 0, Math.PI * 2);
+                        ctx.fillStyle = `hsl(${(i+j) * 30}, 70%, 60%)`;
+                        ctx.fill();
+                    }
+                }
+                break;
+        }
+
+        const img = new Image();
+        img.src = canvas.toDataURL();
+        img.className = 'test-image';
+        img.onclick = () => selectTestImage(img.src);
+        gallery.appendChild(img);
+    });
+}
+
+function selectTestImage(src) {
+    currentImage = src;
+    document.getElementById('preview').src = src;
+}
+
+// Convert text to binary
+function textToBinary(text) {
+    return text.split('').map(char => 
+        char.charCodeAt(0).toString(2).padStart(8, '0')
+    ).join('');
+}
+
+// Convert binary to text
+function binaryToText(binary) {
+    let text = '';
+    for (let i = 0; i < binary.length; i += 8) {
+        text += String.fromCharCode(parseInt(binary.substr(i, 8), 2));
+    }
+    return text;
+}
+
+// Encode message
+function encodeMessage() {
+    if (!currentImage) {
+        alert('Please select a test image first');
+        return;
+    }
+
+    const messageInput = document.getElementById('messageInput');
+    const preview = document.getElementById('preview');
+    const message = messageInput.value;
+
+    if (!message) {
+        alert('Please enter a message');
+        return;
+    }
+
+    const img = new Image();
+    img.src = currentImage;
+    
+    img.onload = () => {
+        const canvas = document.createElement('canvas');
+        const ctx = canvas.getContext('2d');
+        canvas.width = img.width;
+        canvas.height = img.height;
+        ctx.drawImage(img, 0, 0);
+
+        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
+        const pixels = imageData.data;
+
+        const binaryMessage = textToBinary(message) + '00000000';
+        
+        if (binaryMessage.length > pixels.length * 3) {
+            alert('Message too long for this image');
+            return;
+        }
+
+        let binaryIndex = 0;
+        for (let i = 0; i < pixels.length; i += 4) {
+            if (binaryIndex < binaryMessage.length) {
+                pixels[i] = (pixels[i] & 254) | parseInt(binaryMessage[binaryIndex++]);
+            }
+            if (binaryIndex < binaryMessage.length) {
+                pixels[i + 1] = (pixels[i + 1] & 254) | parseInt(binaryMessage[binaryIndex++]);
+            }
+            if (binaryIndex < binaryMessage.length) {
+                pixels[i + 2] = (pixels[i + 2] & 254) | parseInt(binaryMessage[binaryIndex++]);
+            }
+        }
+
+        ctx.putImageData(imageData, 0, 0);
+        preview.src = canvas.toDataURL();
+        currentImage = canvas.toDataURL();
+    };
+}
+
+// Decode message
+function decodeMessage() {
+    if (!currentImage) {
+        alert('Please encode a message first');
+        return;
+    }
+
+    const img = new Image();
+    img.src = currentImage;
+    
+    img.onload = () => {
+        const canvas = document.createElement('canvas');
+        const ctx = canvas.getContext('2d');
+        canvas.width = img.width;
+        canvas.height = img.height;
+        ctx.drawImage(img, 0, 0);
+
+        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
+        const pixels = imageData.data;
+
+        let binaryMessage = '';
+        for (let i = 0; i < pixels.length; i += 4) {
+            binaryMessage += (pixels[i] & 1);
+            binaryMessage += (pixels[i + 1] & 1);
+            binaryMessage += (pixels[i + 2] & 1);
+        }
+
+        const delimiter = '00000000';
+        const endIndex = binaryMessage.indexOf(delimiter);
+        if (endIndex === -1) {
+            document.getElementById('decodedMessage').value = 'No hidden message found';
+            return;
+        }
+
+        const message = binaryToText(binaryMessage.substring(0, endIndex));
+        document.getElementById('decodedMessage').value = message;
+    };
+}
+
+// Generate test images when page loads
+window.onload = generateTestImages;
+</script>
+</body>
+</html>
+```
+
+This enhanced version includes:
+
+1. Six different test images with various patterns:
+   - Gradient
+   - Concentric circles
+   - Colorful squares
+   - Triangles
+   - Stripes
+   - Dots pattern
+
+2. A gallery of clickable test images
+3. Improved UI with better styling
+4. No need for file upload
+5. Simple click-to-select functionality
+
+To use:
+
+1. Click on any test image from the gallery
+2. Enter your secret message
+3. Click "Encode" to hide the message
+4. Click "Decode" to reveal the hidden message
+
+The test images are generated programmatically and provide enough complexity and color variation to effectively demonstrate the steganography process. Each image has different patterns and colors, making it easier to see how the encoding process affects different types of images.
+
+The interface is more user-friendly and requires no file uploads, making it perfect for quick testing and demonstration purposes.
+
+
