+To provide an initial image for testing purposes, we can generate a simple placeholder image using the Canvas API directly in the webpage. This allows users to test the encoding and decoding functionality without needing to upload their own image.
+
+Below is the updated and complete code, which includes a "Generate Test Image" button that creates a test image for use in the steganography tool:
+
+```html
+<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>Steganography Tool</title>
+  <script>
+    // Helper function to convert text to binary
+    function textToBinary(text) {
+      return text.split('').map(char => char.charCodeAt(0).toString(2).padStart(8, '0')).join('');
+    }
+
+    // Helper function to convert binary to text
+    function binaryToText(binary) {
+      return binary.match(/.{1,8}/g).map(byte => String.fromCharCode(parseInt(byte, 2))).join('');
+    }
+
+    // Generate a test image
+    function generateTestImage() {
+      const canvas = document.getElementById("canvas");
+      const ctx = canvas.getContext("2d");
+
+      // Create a placeholder image
+      canvas.width = 300;
+      canvas.height = 300;
+
+      // Draw a simple pattern on the canvas
+      ctx.fillStyle = "#87CEEB"; // sky blue
+      ctx.fillRect(0, 0, canvas.width, canvas.height);
+
+      ctx.fillStyle = "#FFD700"; // yellow (sun)
+      ctx.beginPath();
+      ctx.arc(150, 100, 50, 0, Math.PI * 2);
+      ctx.fill();
+
+      ctx.fillStyle = "#228B22"; // green (ground)
+      ctx.fillRect(0, 200, canvas.width, 100);
+
+      // Convert canvas to image and display it
+      const output = document.getElementById("output");
+      output.src = canvas.toDataURL();
+    }
+
+    // Encode message into image
+    function encodeMessage() {
+      const imageInput = document.getElementById("imageInput");
+      const message = document.getElementById("messageInput").value;
+      const canvas = document.getElementById("canvas");
+      const ctx = canvas.getContext("2d");
+      const output = document.getElementById("output");
+
+      if (!output.src || !message) {
+        alert("Please generate or upload an image and enter a message to encode.");
+        return;
+      }
+
+      const img = new Image();
+      img.src = output.src;
+
+      img.onload = function () {
+        canvas.width = img.width;
+        canvas.height = img.height;
+        ctx.drawImage(img, 0, 0);
+
+        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
+        const binaryMessage = textToBinary(message) + '00000000'; // Add a null terminator
+        let messageIndex = 0;
+
+        for (let i = 0; i < imageData.data.length; i += 4) {
+          if (messageIndex < binaryMessage.length) {
+            imageData.data[i] = (imageData.data[i] & 0xFE) | parseInt(binaryMessage[messageIndex]); // Modify the red channel
+            messageIndex++;
+          }
+        }
+
+        ctx.putImageData(imageData, 0, 0);
+
+        output.src = canvas.toDataURL();
+        document.getElementById("downloadLink").href = canvas.toDataURL();
+        document.getElementById("downloadLink").style.display = "block";
+      };
+    }
+
+    // Decode message from image
+    function decodeMessage() {
