+Below is an updated React component that includes a button to export the finished business card as a PDF. We’ll use the “html2canvas” and “jspdf” libraries to capture and convert the preview area into a PDF file. To install these libraries, run:  
+npm install html2canvas jspdf  
+
+Explanation of Key Additions:
+• We import “html2canvas” and “jspdf” at the top of the file.  
+• A React ref “cardRef” is defined and attached to the preview card.  
+• The “handleExportPDF” function captures the referenced div and generates a PDF download.  
+
+Below is the complete code. You can place it directly in your React environment, including the needed imports:
+
+```jsx
+import React, { useState, useRef } from "react";
+import html2canvas from "html2canvas";
+import jsPDF from "jspdf";
+
+function BusinessCardCreator() {
+  const [name, setName] = useState("");
+  const [title, setTitle] = useState("");
+  const [email, setEmail] = useState("");
+  const [phone, setPhone] = useState("");
+  const [imageData, setImageData] = useState("");
+  const [template, setTemplate] = useState("light");
+
+  // Create a ref to capture the preview area
+  const cardRef = useRef(null);
+
+  const handleFileChange = (e) => {
+    const file = e.target.files[0];
+    if (!file) {
+      setImageData("");
+      return;
+    }
+    const reader = new FileReader();
+    reader.onloadend = () => {
+      setImageData(reader.result.toString());
+    };
+    reader.readAsDataURL(file);
+  };
+
+  const renderTemplateClasses = () => {
+    switch (template) {
+      case "dark":
+        return "bg-gray-800 text-white";
+      case "colorful":
+        return "bg-indigo-200 text-indigo-900";
+      default:
+        return "bg-white text-gray-800 border border-gray-300";
+    }
+  };
+
+  // Function to export the card as a PDF
+  const handleExportPDF = async () => {
+    if (!cardRef.current) return;
+    const canvas = await html2canvas(cardRef.current);
+    const imgData = canvas.toDataURL("image/png");
+    const pdf = new jsPDF("p", "pt", "a4");
+    const imgWidth = 300; // Scale the image size
+    const pageWidth = pdf.internal.pageSize.getWidth();
+    const ratio = imgWidth / canvas.width;
+    const imgHeight = canvas.height * ratio;
+
+    // Calculate the left margin to center the card on the PDF
+    const xOffset = (pageWidth - imgWidth) / 2;
+    pdf.addImage(imgData, "PNG", xOffset, 50, imgWidth, imgHeight);
+    pdf.save("business_card.pdf");
+  };
+
+  return (
+    <div className="p-4 min-h-screen bg-gray-100">
+      <h1 className="text-2xl font-bold mb-4">Digital Business Card Creator</h1>
+      <div className="flex flex-col lg:flex-row gap-8">
+        {/* Form Section */}
+        <div className="lg:w-1/2 p-4 bg-white rounded shadow">
+          <div className="mb-4">
+            <label className="block font-semibold mb-1">Name</label>
+            <input
+              type="text"
+              value={name}
+              onChange={(e) => setName(e.target.value)}
+              className="border border-gray-300 rounded w-full p-2"
+              placeholder="Your Name"
+            />
+          </div>
+          <div className="mb-4">
+            <label className="block font-semibold mb-1">Title</label>
+            <input
+              type="text"
+              value={title}
+              onChange={(e) => setTitle(e.target.value)}
+              className="border border-gray-300 rounded w-full p-2"
+              placeholder="Position / Title"
+            />
+          </div>
+          <div className="mb-4">
+            <label className="block font-semibold mb-1">Email</label>
+            <input
+              type="email"
+              value={email}
+              onChange={(e) => setEmail(e.target.value)}
+              className="border border-gray-300 rounded w-full p-2"
+              placeholder="Email Address"
+            />
+          </div>
+          <div className="mb-4">
+            <label className="block font-semibold mb-1">Phone</label>
+            <input
+              type="tel"
+              value={phone}
+              onChange={(e) => setPhone(e.target.value)}
+              className="border border-gray-300 rounded w-full p-2"
+              placeholder="Phone Number"
+            />
+          </div>
+          <div className="mb-4">
+            <label className="block font-semibold mb-1">Profile Image</label>
+            <input
+              type="file"
+              accept="image/*"
+              onChange={handleFileChange}
+              className="block"
+            />
+          </div>
+          <div className="mb-4">
+            <label className="block font-semibold mb-1">Template Style</label>
+            <select
+              value={template}
+              onChange={(e) => setTemplate(e.target.value)}
+              className="border border-gray-300 rounded w-full p-2"
+            >
+              <option value="light">Light</option>
+              <option value="dark">Dark</option>
+              <option value="colorful">Colorful</option>
+            </select>
+          </div>
+          <div>
+            <button
+              onClick={handleExportPDF}
+              className="bg-green-600 text-white py-2 px-4 rounded hover:bg-green-700"
+            >
+              Export as PDF
+            </button>
+          </div>
+        </div>
+
+        {/* Preview Section */}
+        <div className="lg:w-1/2">
+          <h2 className="text-xl font-semibold mb-4">Preview</h2>
+          <div
+            ref={cardRef}
+            className={`rounded shadow p-4 w-full max-w-sm ${renderTemplateClasses()}`}
+          >
+            <div className="flex justify-center mb-4">
+              {imageData ? (
+                <img
+                  src={imageData}
+                  alt="Profile"
+                  className="w-32 h-32 rounded-full object-cover"
+                />
+              ) : (
+                <img
+                  src="/api/placeholder/400/320"
+                  alt="placeholder"
+                  className="w-32 h-32 rounded-full object-cover"
+                />
+              )}
+            </div>
+            <div className="text-center">
+              <h3 className="text-xl font-bold mb-1">{name || "Your Name"}</h3>
+              <p className="mb-2">{title || "Position / Title"}</p>
+              <p>{email || "Email Address"}</p>
+              <p>{phone || "Phone Number"}</p>
+            </div>
+          </div>
+        </div>
+      </div>
+    </div>
+  );
+}
+
+export default BusinessCardCreator;
+```
