+Here's the updated solution with the ability to input mass, position, and velocity for each object:
+
+```javascript
+import React, { useState, useEffect, useRef } from "react";
+import { nanoid } from "nanoid";
+
+const GRAVITY_CONSTANT = 0.1; // Arbitrary gravitational constant for simulation
+
+const GravitySimulator = () => {
+  const canvasRef = useRef(null);
+  const [objects, setObjects] = useState([]);
+  const [isRunning, setIsRunning] = useState(true);
+  const [newObject, setNewObject] = useState({
+    mass: 10,
+    x: 400,
+    y: 300,
+    vx: 0,
+    vy: 0,
+  });
+
+  const addObject = () => {
+    setObjects((prev) => [
+      ...prev,
+      {
+        id: nanoid(),
+        mass: newObject.mass,
+        x: newObject.x,
+        y: newObject.y,
+        vx: newObject.vx,
+        vy: newObject.vy,
+        path: [],
+      },
+    ]);
+  };
+
+  const resetSimulation = () => {
+    setObjects([]);
+  };
+
+  useEffect(() => {
+    const canvas = canvasRef.current;
+    const ctx = canvas.getContext("2d");
+    let animationFrameId;
+
+    const updateSimulation = () => {
+      ctx.clearRect(0, 0, canvas.width, canvas.height);
+
+      // Calculate gravitational forces and update positions
+      objects.forEach((obj1, index1) => {
+        let fx = 0;
+        let fy = 0;
+
+        objects.forEach((obj2, index2) => {
+          if (index1 !== index2) {
+            const dx = obj2.x - obj1.x;
+            const dy = obj2.y - obj1.y;
+            const distance = Math.sqrt(dx * dx + dy * dy) || 1;
+            const force =
+              (GRAVITY_CONSTANT * obj1.mass * obj2.mass) / (distance * distance);
+
+            fx += (force * dx) / distance;
+            fy += (force * dy) / distance;
+          }
+        });
+
+        // Update velocity
+        obj1.vx += fx / obj1.mass;
+        obj1.vy += fy / obj1.mass;
+
+        // Update position
+        obj1.x += obj1.vx;
+        obj1.y += obj1.vy;
+
+        // Save trajectory
+        obj1.path.push([obj1.x, obj1.y]);
+        if (obj1.path.length > 100) obj1.path.shift();
+      });
+
+      // Draw objects and their paths
+      objects.forEach((obj) => {
+        // Draw trajectory
+        ctx.beginPath();
+        obj.path.forEach(([px, py], i) => {
+          if (i === 0) ctx.moveTo(px, py);
+          else ctx.lineTo(px, py);
+        });
+        ctx.strokeStyle = "rgba(0, 0, 255, 0.5)";
+        ctx.stroke();
+
+        // Draw object
+        ctx.beginPath();
+        ctx.arc(obj.x, obj.y, Math.sqrt(obj.mass), 0, 2 * Math.PI);
+        ctx.fillStyle = "red";
+        ctx.fill();
+      });
+
+      if (isRunning) {
+        animationFrameId = requestAnimationFrame(updateSimulation);
+      }
+    };
+
+    updateSimulation();
+
+    return () => {
+      cancelAnimationFrame(animationFrameId);
+    };
+  }, [objects, isRunning]);
+
+  return (
+    <div className="flex flex-col items-center p-4">
+      <h1 className="text-2xl font-bold mb-4">Gravity Simulator</h1>
+      <canvas
+        ref={canvasRef}
+        width={800}
+        height={600}
+        className="border border-gray-300 mb-4"
+      />
+      <div className="flex flex-col items-center space-y-4 mb-4">
+        <div className="flex space-x-4">
+          <div>
+            <label className="block text-sm font-medium">Mass</label>
+            <input
+              type="number"
+              value={newObject.mass}
+              onChange={(e) =>
+                setNewObject({ ...newObject, mass: parseFloat(e.target.value) })
+              }
+              className="border rounded px-2 py-1"
+            />
+          </div>
+          <div>
+            <label className="block text-sm font-medium">X Position</label>
+            <input
+              type="number"
+              value={newObject.x}
+              onChange={(e) =>
+                setNewObject({ ...newObject, x: parseFloat(e.target.value) })
+              }
+              className="border rounded px-2 py-1"
+            />
+          </div>
+          <div>
+            <label className="block text-sm font-medium">Y Position</label>
+            <input
+              type="number"
+              value={newObject.y}
+              onChange={(e) =>
+                setNewObject({ ...newObject, y: parseFloat(e.target.value) })
+              }
+              className="border rounded px-2 py-1"
+            />
+          </div>
+        </div>
+        <div className="flex space-x-4">
+          <div>
+            <label className="block text-sm font-medium">X Velocity</label>
+            <input
+              type="number"
+              value={newObject.vx}
+              onChange={(e) =>
+                setNewObject({ ...newObject, vx: parseFloat(e.target.value) })
+              }
+              className="border rounded px-2 py-1"
+            />
+          </div>
+          <div>
+            <label className="block text-sm font-medium">Y Velocity</label>
+            <input
+              type="number"
+              value={newObject.vy}
+              onChange={(e) =>
+                setNewObject({ ...newObject, vy: parseFloat(e.target.value) })
+              }
+              className="border rounded px-2 py-1"
+            />
+          </div>
+        </div>
+        <button
+          className="bg-green-500 text-white px-4 py-2 rounded"
+          onClick={addObject}
+        >
+          Add Object
+        </button>
+      </div>
+      <div className="flex space-x-4">
+        <button
+          className="bg-blue-500 text-white px-4 py-2 rounded"
+          onClick={() => setIsRunning(!isRunning)}
+        >
+          {isRunning ? "Pause" : "Resume"}
+        </button>
+        <button
+          className="bg-red-500 text-white px-4 py-2 rounded"
+          onClick={resetSimulation}
+        >
