+The following React component demonstrates how to model the itinerary reconstruction as a Hierholzer’s algorithm to find an Eulerian path in a directed graph. In this solution, the flight tickets (directed edges) are used exactly once to form the Eulerian path. Notice that for lexicographical order we sort each departure's destinations in reverse order so that we can use the pop() function during DFS, ensuring we always take the smallest available option.
+
+Below is the complete, self-contained JavaScript code using React and Tailwind classes:
+
+```javascript
+import React, { useState, useEffect } from "react";
+
+const ItineraryReconstruction = () => {
+  // Function implementing Hierholzer's algorithm for Eulerian path reconstruction.
+  function findItinerary(tickets) {
+    const graph = {};
+    // Build the graph: for each departure, add its destination.
+    for (const [from, to] of tickets) {
+      if (!graph[from]) {
+        graph[from] = [];
+      }
+      graph[from].push(to);
+    }
+    // Sort destinations in reverse lexicographical order.
+    for (const from in graph) {
+      graph[from].sort().reverse();
+    }
+    const itinerary = [];
+    // DFS function: while there are tickets to use from the current airport,
+    // recursively visit the next airport. Once finished, add the airport to itinerary.
+    function dfs(airport) {
+      while (graph[airport] && graph[airport].length) {
+        dfs(graph[airport].pop());
+      }
+      itinerary.push(airport);
+    }
+    // Start the DFS from "JFK".
+    dfs("JFK");
+    // Reverse to get the correct order because airports are added postvisitation.
+    return itinerary.reverse();
+  }
+
+  // Sample list of flight tickets.
+  const tickets = [
+    ["JFK", "MUC"],
+    ["JFK", "ATL"],
+    ["MUC", "LHR"],
+    ["ATL", "JFK"],
+    ["ATL", "SFO"],
+    ["SFO", "ATL"],
+  ];
+
+  // State to store the reconstructed itinerary.
+  const [itinerary, setItinerary] = useState([]);
+
+  // Run the algorithm when the component loads.
+  useEffect(() => {
+    const result = findItinerary(tickets);
+    setItinerary(result);
+  }, []);
+
+  return (
+    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
+      <div className="bg-white p-6 rounded shadow-md w-full max-w-md">
+        <h1 className="text-2xl font-bold mb-4">
+          Eulerian Path Reconstruction
+        </h1>
+        <p className="font-medium mb-2">Flight Tickets:</p>
+        <ul className="list-disc list-inside mb-4">
+          {tickets.map((ticket, idx) => (
+            <li key={idx}>
+              {ticket[0]} → {ticket[1]}
+            </li>
+          ))}
+        </ul>
+        <p className="font-medium mb-2">
+          Reconstructed Itinerary (Using Hierholzer’s Algorithm):
+        </p>
+        <div className="p-3 bg-gray-200 rounded">
+          {itinerary.join(" → ")}
+        </div>
+      </div>
+    </div>
+  );
+};
+
+export default ItineraryReconstruction;
+```
+
+Explanation:
+
+1. The function findItinerary builds a directed graph from the flight tickets.
+2. For each departure, we sort the list of destination airports in reverse lexicographical order to efficiently pop the smallest element during DFS.
+3. We perform a depth-first search from "JFK". As each branch is completed, the airport is appended to the itinerary.
+4. Because the itinerary is built in reverse order, we reverse the final result.
+5. The React component displays the original tickets and the reconstructed itinerary using Tailwind classes for styling.
+
+This component is self-contained and exports a default React component that can be rendered in any React application without additional setup.
