+Below is a comprehensive C++ program that demonstrates how to implement Dijkstra's algorithm to find the shortest paths from a given source node to all other nodes in a weighted graph with non-negative edge weights. The solution is entirely contained within a single .cpp file, uses only the C++ standard library, and does not depend on any external input. Several test cases are embedded in the main function to illustrate correctness, efficiency, and clarity.
+
+Explanation and Approach:
+1. We utilize the C++ standard library’s priority queue for selecting the next edge with the minimum distance during Dijkstra’s algorithm (O((V + E) log V) complexity).  
+2. The graph is represented using an adjacency list, where each element is a vector of (neighbor, weight) pairs.  
+3. We use an array (or std::vector) to track distances from the source, initialized to a large (infinite) value.  
+4. The algorithm extracts the node with the smallest current distance from the priority queue, then relaxes the edges going out of that node by checking if the new distance is smaller than the current stored distance.  
+5. We provide multiple test graphs in the main function. Each test is labeled, and we print the final shortest path distances to stdout.  
+
+This program follows modern C++ best practices by using meaningful variable names, inline comments for clarity, no external dependencies, and carefully managing potential edge cases.
+
+--------------------------------------------------------------------------------
+
+```cpp
+#include <iostream>
+#include <vector>
+#include <queue>
+#include <limits>
+#include <utility>
+
+// Uses: <vector>, <queue>, <limits>, <utility>, <iostream>
+
+// Function to perform Dijkstra's algorithm. 
+// Parameters:
+//   graph: adjacency list, graph[u] is a vector of (neighbor, weight) pairs
+//   source: the starting node for the shortest path search
+// Returns:
+//   A vector of int distances from the source to every other node
+std::vector<int> runDijkstra(const std::vector<std::vector<std::pair<int,int>>>& graph, int source) {
+    // Number of vertices
+    int V = static_cast<int>(graph.size());
+
+    // Initialize distance array
+    std::vector<int> dist(V, std::numeric_limits<int>::max());
+    dist[source] = 0;
+
+    // Min-heap priority queue, storing (distance, node) pairs
+    std::priority_queue<
+        std::pair<int,int>,
+        std::vector<std::pair<int,int>>,
+        std::greater<std::pair<int,int>>
+    > pq;
+
+    // Push the source with distance = 0
+    pq.push({0, source});
+
+    // Process the queue
+    while (!pq.empty()) {
+        // Extract the top (smallest distance) element
+        auto [currentDist, u] = pq.top();
+        pq.pop();
+
+        // If we've already found a better distance, skip
+        if (currentDist > dist[u]) {
+            continue;
+        }
+
+        // For each neighbor of u
+        for (auto &edge : graph[u]) {
+            int v = edge.first;   // neighbor
+            int w = edge.second;  // edge weight
+
+            // Check if we can improve the distance to v
+            if (dist[u] + w < dist[v]) {
+                dist[v] = dist[u] + w;
+                pq.push({dist[v], v});
+            }
+        }
+    }
+    return dist;
+}
+
+int main() {
+    // Test Case 1
+    {
+        // Simple graph with 4 nodes: 0, 1, 2, 3
+        // Edges (directed for illustration):
+        // 0->1(4), 0->2(12), 1->2(8), 1->3(15), 2->3(7)
+        std::vector<std::vector<std::pair<int,int>>> graph(4);
+        graph[0].push_back({1, 4});
+        graph[0].push_back({2, 12});
+        graph[1].push_back({2, 8});
+        graph[1].push_back({3, 15});
+        graph[2].push_back({3, 7});
+
+        int source = 0;
+        std::vector<int> distances = runDijkstra(graph, source);
+
+        std::cout << "Test Case 1: Dijkstra from node " << source << "\n";
+        std::cout << "Distances: ";
+        for (size_t i = 0; i < distances.size(); i++) {
+            std::cout << distances[i];
+            if (i < distances.size() - 1) std::cout << " ";
+        }
+        std::cout << "\n\n";
+    }
+
+    // Test Case 2
+    {
+        // A slightly larger graph with 5 nodes: 0, 1, 2, 3, 4
+        // Weighted edges (directed for demonstration):
+        // 0->1(2), 0->3(7), 1->2(3), 1->3(1), 2->4(5), 3->2(2), 3->4(4)
+        std::vector<std::vector<std::pair<int,int>>> graph(5);
+        graph[0].push_back({1, 2});
+        graph[0].push_back({3, 7});
+        graph[1].push_back({2, 3});
+        graph[1].push_back({3, 1});
+        graph[2].push_back({4, 5});
+        graph[3].push_back({2, 2});
+        graph[3].push_back({4, 4});
+
+        int source = 0;
+        std::vector<int> distances = runDijkstra(graph, source);
+
+        std::cout << "Test Case 2: Dijkstra from node " << source << "\n";
+        std::cout << "Distances: ";
+        for (size_t i = 0; i < distances.size(); i++) {
+            std::cout << distances[i];
+            if (i < distances.size() - 1) std::cout << " ";
+        }
+        std::cout << "\n";
+    }
+
+    return 0;
+}
