+    int V1 = 5; // Number of vertices
+    vector<vector<pair<int, int>>> graph1(V1);
+    graph1[0] = {{1, 4}, {2, 8}};
+    graph1[1] = {{0, 4}, {2, 2}, {3, 5}};
+    graph1[2] = {{0, 8}, {1, 2}, {4, 9}};
+    graph1[3] = {{1, 5}, {4, 4}};
+    graph1[4] = {{2, 9}, {3, 4}};
+    int source1 = 0;
+
+    // Compute shortest distances
+    vector<int> result1 = dijkstra(V1, graph1, source1);
+
+    // Output the result for test case 1
+    cout << "Test Case 1: ";
+    for (int dist : result1) {
+        if (dist == numeric_limits<int>::max()) {
+            cout << "INF ";
+        } else {
+            cout << dist << " ";
+        }
+    }
+    cout << endl;
+
+    // Hard-coded test case 2
+    int V2 = 4;
+    vector<vector<pair<int, int>>> graph2(V2);
+    graph2[0] = {{1, 1}, {2, 4}};
+    graph2[1] = {{0, 1}, {2, 2}, {3, 6}};
+    graph2[2] = {{0, 4}, {1, 2}, {3, 3}};
+    graph2[3] = {{1, 6}, {2, 3}};
+    int source2 = 0;
+
+    // Compute shortest distances
+    vector<int> result2 = dijkstra(V2, graph2, source2);
+
+    // Output the result for test case 2
+    cout << "Test Case 2: ";
+    for (int dist : result2) {
+        if (dist == numeric_limits<int>::max()) {
+            cout << "INF ";
+        } else {
+            cout << dist << " ";
+        }
+    }
+    cout << endl;
+
+    return 0;
+}
+```
