+Below is a concise explanation of the two-pointer approach, followed by a self-contained JavaScript code snippet that you can directly run. The code includes a function to calculate the maximum container area, and then demonstrates its usage with a few example arrays.
+
+Explanation:
+1. Initialize two pointers: one at the start (left) and one at the end (right) of the array.
+2. At each step, calculate the area: distance between pointers × the smaller of the two heights.
+3. Update the maximum area accordingly.
+4. Move whichever pointer is pointing to the smaller height to try to find a higher line, which might yield a larger area.
+5. Continue until the two pointers meet.
+
+```javascript
+// Two-pointer solution to find the maximum container area.
+function maxContainerArea(heights) {
+  let left = 0;
+  let right = heights.length - 1;
+  let maxArea = 0;
+
+  while (left < right) {
+    const distance = right - left;
+    const currentHeight = Math.min(heights[left], heights[right]);
+    const currentArea = distance * currentHeight;
+    maxArea = Math.max(maxArea, currentArea);
+
+    if (heights[left] < heights[right]) {
+      left++;
+    } else {
+      right--;
+    }
+  }
+
+  return maxArea;
+}
+
+// Example usage:
+const arrays = [
+  [1, 8, 6, 2, 5, 4, 8, 3, 7],
+  [1, 1],
+  [4, 3, 2, 1, 4],
+  [1, 2, 1]
+];
+
+arrays.forEach(arr => {
+  console.log(`Heights: [${arr}] | Max Area: ${maxContainerArea(arr)}`);
+});
+```
