+Below is a self-contained JavaScript program that uses a binary search approach to find a peak in a given array. The “peak” definition is the same as before, but we’ll focus on returning just one peak index using this binary search method:
+
+Explanation:
+1. We maintain two pointers, left and right.  
+2. While left < right, we pick mid = (left + right) // 2.  
+3. If nums[mid] < nums[mid + 1], we move left to mid + 1 because the rise on the right side guarantees a peak exists on that side.  
+4. Otherwise, a peak exists on the left side (including mid), so we move right to mid.  
+5. Eventually left and right converge to the same index, which is one valid peak index.
+
+```javascript
+// A JavaScript Runner Program
+
+// Example array (no two consecutive elements are equal)
+const nums = [1, 3, 2, 5, 4, 6, 2, 8];
+
+// Binary search approach to find one peak index
+function findPeakIndex(nums) {
+  let left = 0;
+  let right = nums.length - 1;
+
+  while (left < right) {
+    const mid = Math.floor((left + right) / 2);
+    // If mid is less than mid+1, peak must be on the right side
+    if (nums[mid] < nums[mid + 1]) {
+      left = mid + 1;
+    } else {
+      // Otherwise, there is a peak on the left side or at mid
+      right = mid;
+    }
+  }
+  return left;
+}
+
+// Use the function and log the result
+const peakIdx = findPeakIndex(nums);
+console.log("Array:", nums);
+console.log("Peak Index Found By Binary Search:", peakIdx);
+console.log("Peak Value:", nums[peakIdx]);
+```
