+      let bestVal = -Infinity;
+      let move = -1;
+      for (let i = 0; i < currentBoard.length; i++) {
+        if (!currentBoard[i]) {
+          currentBoard[i] = aiPlayer;
+          let moveVal = minimax(currentBoard, 0, false);
+          currentBoard[i] = null;
+          if (moveVal > bestVal) {
