+      const winnerX = checkWin(humanPlayer);
+      const winnerO = checkWin(aiPlayer);
+
+      if (winnerO) return 10 - depth;
+      if (winnerX) return depth - 10;
+      if (isBoardFull(tempBoard)) return 0;
+
+      if (isMaximizing) {
+        let best = -Infinity;
+        for (let i = 0; i < tempBoard.length; i++) {
+          if (!tempBoard[i]) {
+            tempBoard[i] = aiPlayer;
+            best = Math.max(best, minimax(tempBoard, depth + 1, false));
+            tempBoard[i] = null;
+          }
+        }
+        return best;
+      } else {
+        let best = Infinity;
+        for (let i = 0; i < tempBoard.length; i++) {
+          if (!tempBoard[i]) {
+            tempBoard[i] = humanPlayer;
+            best = Math.min(best, minimax(tempBoard, depth + 1, true));
+            tempBoard[i] = null;
+          }
+        }
