+import React, { useState, useRef, KeyboardEvent, ClipboardEvent, ChangeEvent, useEffect } from 'react';
+
+const OTPInput: React.FC = () => {
+  const [otp, setOtp] = useState<string[]>(new Array(6).fill(''));
+  const [error, setError] = useState<boolean>(false);
+  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);
+
+  // Auto-submit when all 6 digits are filled
+  useEffect(() => {
+    const isComplete = otp.every(digit => digit.trim() !== '');
+    if (isComplete) {
+      handleSubmit();
+    }
+  }, [otp]);
+
+  const handleChange = (index: number, e: ChangeEvent<HTMLInputElement>) => {
+    const value = e.target.value;
+    
+    // Only allow numeric input
+    if (!/^\d*$/.test(value)) return;
+
+    const newOtp = [...otp];
+    newOtp[index] = value;
+    setOtp(newOtp);
+
+    // Automatically move to next input if current is filled
+    if (value && index < 5) {
+      inputRefs.current[index + 1]?.focus();
+    }
+
+    // Clear error state when user starts typing
+    if (error) setError(false);
+  };
+
+  const handleKeyDown = (index: number, e: KeyboardEvent<HTMLInputElement>) => {
+    // Handle backspace to move to previous input
+    if (e.key === 'Backspace' && !otp[index] && index > 0) {
+      inputRefs.current[index - 1]?.focus();
+    }
+  };
+
+  const handlePaste = (e: ClipboardEvent<HTMLInputElement>) => {
+    e.preventDefault();
+    const pastedData = e.clipboardData.getData('text/plain').slice(0, 6);
+    
+    if (/^\d{6}$/.test(pastedData)) {
+      const newOtp = pastedData.split('');
+      setOtp(newOtp);
+      inputRefs.current[5]?.focus();
+    } else {
+      setError(true);
+    }
+  };
+
+  const handleSubmit = () => {
+    const otpString = otp.join('');
+    
+    // Validate OTP (example validation)
+    if (otpString.length === 6) {
+      console.log('OTP Submitted:', otpString);
+      // Simulate verification process
+      if (otpString === '123456') {
+        alert('OTP Verified Successfully!');
+        setError(false);
+      } else {
+        setError(true);
+      }
+    } else {
+      setError(true);
+    }
+  };
+
+  // Check if all inputs are filled
+  const isOtpComplete = otp.every(digit => digit.trim() !== '');
+
+  return (
+    <div className="flex flex-col items-center justify-center min-h-screen bg-gray-100 p-4">
+      <div className="bg-white shadow-md rounded-lg p-8 w-full max-w-md">
+        <h2 className="text-2xl font-bold mb-6 text-center text-gray-800">
+          Two-Factor Authentication
+        </h2>
+        <p className="text-center text-gray-600 mb-6">
+          Please enter the 6-digit code sent to your device
+        </p>
+        
+        <div className="flex justify-center space-x-2 mb-6">
+          {otp.map((digit, index) => (
+            <input
+              key={index}
+              ref={(el) => inputRefs.current[index] = el}
+              type="text"
+              maxLength={1}
+              value={digit}
+              onChange={(e) => handleChange(index, e)}
+              onKeyDown={(e) => handleKeyDown(index, e as unknown as KeyboardEvent<HTMLInputElement>)}
+              onPaste={handlePaste}
+              className={`
+                w-12 h-12 text-center text-2xl border-2 rounded-lg 
+                focus:outline-none focus:ring-2 
+                ${error 
+                  ? 'border-red-500 focus:ring-red-300' 
+                  : 'border-gray-300 focus:border-blue-500 focus:ring-blue-300'
+                }
+              `}
+              aria-label={`OTP digit ${index + 1}`}
+            />
+          ))}
+        </div>
+
+        {error && (
+          <p className="text-red-500 text-center mb-4">
+            Invalid OTP. Please try again.
+          </p>
+        )}
+
+        <button
+          onClick={handleSubmit}
+          disabled={!isOtpComplete}
+          className={`
+            w-full py-3 rounded-lg text-white font-semibold transition-colors
+            ${!isOtpComplete
+              ? 'bg-gray-400 cursor-not-allowed'
+              : 'bg-blue-600 hover:bg-blue-700 active:bg-blue-800'
+            }
+          `}
+        >
+          Verify OTP
+        </button>
+      </div>
+    </div>
+  );
+};
+
+export default OTPInput;
+```
