+### Implementing Cleanup Functions in React
+Cleanup functions are used to remove subscriptions or listeners when a component unmounts. This is important to prevent memory leaks and unexpected behavior.
+
+#### Example: Using `useEffect` with Cleanup
+```javascript
+import React, { useState, useEffect } from 'react';
+
+function Counter() {
+  const [count, setCount] = useState(0);
+
+  useEffect(() => {
+    const intervalId = setInterval(() => {
+      setCount(count + 1);
+    }, 1000);
+
+    // Cleanup function to remove the interval
+    return () => {
+      clearInterval(intervalId);
+    };
+  }, [count]);
+
+  return (
+    <div className="flex flex-col items-center justify-center h-screen">
+      <h1 className="text-3xl font-bold mb-4">Count: {count}</h1>
+    </div>
+  );
+}
+
+export default Counter;
+```
+
+#### Explanation:
+1. We define a `Counter` component that uses `useState` to store the count.
+2. We use `useEffect` to set up an interval that increments the count every second.
+3. We return a function from the effect function to clean up the interval when the component is unmounted or the count changes.
+4. The cleanup function is called when the component is unmounted or the effect is re-run.
+
+#### Example: Using `useEffect` with Multiple Cleanup Functions
+```javascript
+import React, { useState, useEffect } from 'react';
+
+function User() {
+  const [user, setUser] = useState(null);
+  const [count, setCount] = useState(0);
+
+  useEffect(() => {
+    const intervalId = setInterval(() => {
+      setCount(count + 1);
+    }, 1000);
+
+    // Fetch user data from an API
+    fetch('https://jsonplaceholder.typicode.com/users/1')
+      .then(response => response.json())
+      .then(data => setUser(data));
+
+    // Cleanup function to remove the interval and user data
+    return () => {
+      clearInterval(intervalId);
+      setUser(null);
+    };
+  }, [count]);
+
+  if (!user) return <div>Loading...</div>;
+
+  return (
+    <div className="flex flex-col items-center justify-center h-screen">
+      <h1 className="text-3xl font-bold mb-4">{user.name}</h1>
+      <p className="text-lg">{user.email}</p>
+      <h2 className="text-2xl font-bold mb-4">Count: {count}</h2>
+    </div>
+  );
+}
+
+export default User;
+```
+
+#### Explanation:
+1. We define a `User` component that uses `useState` to store the user data and count.
+2. We use `useEffect` to set up an interval that increments the count every second and fetches the user data from an API.
+3. We return a function from the effect function to clean up the interval and user data when the component is unmounted or the count changes.
+4. The cleanup function is called when the component is unmounted or the effect is re-run.
+
+#### Best Practices:
+* Always clean up after your effects by returning a function from the effect function.
+* Use the dependency array to control when the effect runs.
+* Avoid using `useEffect` to update state that is not related to the effect.
+
+#### Example: Using `useEffect` with Event Listeners
+```javascript
+import React, { useState, useEffect } from 'react';
+
+function MousePosition() {
+  const [x, setX] = useState(0);
+  const [y, setY] = useState(0);
+
+  useEffect(() => {
+    const handleMouseMove = (event) => {
+      setX(event.clientX);
+      setY(event.clientY);
+    };
+
+    // Add event listener to the document
+    document.addEventListener('mousemove', handleMouseMove);
+
+    // Cleanup function to remove the event listener
+    return () => {
+      document.removeEventListener('mousemove', handleMouseMove);
+    };
+  }, []);
+
+  return (
+    <div className="flex flex-col items-center justify-center h-screen">
+      <h1 className="text-3xl font-bold mb-4">Mouse Position:</h1>
+      <p className="text-lg">X: {x}, Y: {y}</p>
+    </div>
+  );
+}
+
+export default MousePosition;
+```
+
+#### Explanation:
+1. We define a `MousePosition` component that uses `useState` to store the mouse position.
+2. We use `useEffect` to add an event listener to the document that updates the mouse position when the mouse is moved.
+3. We return a function from the effect function to clean up the event listener when the component is unmounted.
+4. The cleanup function is called when the component is unmounted or the effect is re-run.
