+      color: #4a4a4a;
+    }
+    header {
+      text-align: center;
+      padding: 1rem;
+      background-color: #d4a373;
+      color: white;
+      font-size: 1.5rem;
+    }
+    .search-container {
+      text-align: center;
+      margin: 1rem 0;
+    }
+    .search-container input {
+      padding: 0.5rem;
+      width: 50%;
+      border: 2px solid #d4a373;
+      border-radius: 5px;
+      font-size: 1rem;
+    }
+    .sequence-grid {
+      display: grid;
+      grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
+      gap: 1rem;
+      padding: 1rem;
+    }
+    .tile {
+      background-color: #fff;
+      border: 1px solid #d4a373;
+      border-radius: 10px;
+      padding: 1rem;
+      text-align: center;
+      position: relative;
+      overflow: hidden;
+      transition: transform 0.3s ease;
+      box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
+    }
+    .tile:hover {
+      transform: scale(1.05);
+    }
+    .tile .hover-info {
+      position: absolute;
+      top: 0;
+      left: 0;
+      width: 100%;
+      height: 100%;
+      background-color: rgba(212, 163, 115, 0.9);
+      color: white;
+      display: flex;
+      flex-direction: column;
+      justify-content: center;
+      align-items: center;
+      opacity: 0;
+      transition: opacity 0.3s ease;
+    }
+    .tile:hover .hover-info {
+      opacity: 1;
+    }
+    .tile .value {
+      font-size: 1.5rem;
+      font-weight: bold;
