+  <header>Narayana's Cows Sequence</header>
+  <div class="search-container">
+    <input type="text" id="search-bar" placeholder="Search by index or value..." oninput="filterTiles()">
+  </div>
+  <div class="sequence-grid" id="sequence-grid"></div>
+
+  <script>
+    // Generate Narayana's Cows Sequence
+    function generateNarayanaSequence(n) {
+      const sequence = [1, 1, 1];
+      for (let i = 3; i < n; i++) {
+        sequence.push(sequence[i - 1] + sequence[i - 3]);
+      }
+      return sequence;
+    }
+
+    // Render Tiles
+    function renderTiles(sequence) {
+      const grid = document.getElementById("sequence-grid");
+      grid.innerHTML = ""; // Clear previous tiles
+      sequence.forEach((value, index) => {
+        const tile = document.createElement("div");
+        tile.className = "tile";
+        tile.innerHTML = `
+          <div class="value">${value}</div>
+          <div class="hover-info">
+            <p>Index: ${index}</p>
+            <p>"Rustic wisdom of the cows at term ${index}"</p>
+          </div>
+        `;
+        grid.appendChild(tile);
+      });
+    }
+
+    // Filter Tiles by Search
+    function filterTiles() {
+      const query = document.getElementById("search-bar").value.toLowerCase();
+      const tiles = document.querySelectorAll(".tile");
+      tiles.forEach((tile, index) => {
+        const value = tile.querySelector(".value").textContent;
+        if (index.toString().includes(query) || value.includes(query)) {
+          tile.style.display = "block";
+        } else {
+          tile.style.display = "none";
+        }
+      });
+    }
+
+    // Initialize Page
+    const sequence = generateNarayanaSequence(30); // Generate first 30 terms
+    renderTiles(sequence);
+  </script>
+</body>
+</html>
+```
