+In this improved version, we combine our URL shortening API with a polished, Tailwind CSS–powered web interface. The UI lets users input a URL to shorten, displays the shortened result when available, and includes a button to view basic usage analytics in a neat table. All HTML, CSS (via a CDN), and JavaScript are embedded in a single file. Follow the instructions below and run the file with Node.js after installing Express and nanoid via:
+
+  npm install express nanoid
+
+Below is the complete self-contained code:
+
+```javascript
+// Import necessary libraries
+const express = require("express");
+const { nanoid } = require("nanoid");
+
+// Initialize the Express app
+const app = express();
+const port = 3000;
+
+// Use JSON middleware to parse JSON requests
+app.use(express.json());
+
+// In-memory storage for URLs and analytics
+// Structure: { [code]: { originalURL: string, visits: Array<timestamp> } }
+const urlDatabase = {};
+
+// Base URL for shortened links (change as needed)
+const baseUrl = `http://localhost:${port}`;
+
+// Serve the polished UI on the root endpoint
+app.get("/", (req, res) => {
+  // An HTML page with Tailwind CSS from CDN is provided inline.
+  res.send(`
+    <!DOCTYPE html>
+    <html lang="en">
+    <head>
+      <meta charset="UTF-8" />
+      <meta name="viewport" content="width=device-width, initial-scale=1.0" />
+      <title>URL Shortener</title>
+      <link href="https://cdn.jsdelivr.net/npm/tailwindcss@2.2.19/dist/tailwind.min.css" rel="stylesheet">
+    </head>
+    <body class="bg-gray-100 text-gray-800">
+      <div class="container mx-auto p-4">
+        <h1 class="text-3xl font-bold text-center mb-6">URL Shortening Service</h1>
+        
+        <div class="bg-white shadow-md rounded px-8 pt-6 pb-8 mb-4">
+          <h2 class="text-xl font-semibold mb-4">Shorten Your URL</h2>
+          <div class="mb-4">
+            <input id="urlInput" class="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline" type="text" placeholder="Enter URL here">
+          </div>
+          <button id="shortenBtn" class="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline">
+            Shorten URL
+          </button>
+          <div id="result" class="mt-4 text-green-600"></div>
+          <div id="error" class="mt-4 text-red-600"></div>
+        </div>
+        
+        <div class="bg-white shadow-md rounded px-8 pt-6 pb-8">
+          <h2 class="text-xl font-semibold mb-4">Usage Analytics</h2>
+          <button id="analyticsBtn" class="bg-green-500 hover:bg-green-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline mb-4">
+            Load Analytics
+          </button>
+          <div id="analyticsSection">
+            <!-- Analytics table will be inserted here -->
+          </div>
+        </div>
+      </div>
+      
+      <script>
+        // Handle URL shortening
+        document.getElementById('shortenBtn').addEventListener('click', async () => {
+          const urlInput = document.getElementById('urlInput');
+          const result = document.getElementById('result');
+          const error = document.getElementById('error');
+          result.textContent = '';
+          error.textContent = '';
+          const url = urlInput.value.trim();
+          if (!url) {
+            error.textContent = 'Please enter a URL';
+            return;
+          }
+          try {
+            const response = await fetch('/shorten', {
+              method: 'POST',
+              headers: {
+                'Content-Type': 'application/json'
+              },
+              body: JSON.stringify({ url })
+            });
+            const data = await response.json();
+            if (response.ok) {
+              result.innerHTML = 'Shortened URL: <a class="text-blue-500 underline" target="_blank" href="' + data.shortUrl + '">' + data.shortUrl + '</a>';
+              urlInput.value = '';
+            } else {
+              error.textContent = data.error || 'Error shortening URL';
+            }
+          } catch (err) {
+            error.textContent = 'Error connecting to server';
+          }
+        });
+        
+        // Handle fetching analytics
+        document.getElementById('analyticsBtn').addEventListener('click', async () => {
+          const analyticsSection = document.getElementById('analyticsSection');
+          analyticsSection.innerHTML = '';
+          try {
+            const response = await fetch('/analytics');
+            const data = await response.json();
+            if (response.ok) {
+              if (data.analytics.length === 0) {
+                analyticsSection.innerHTML = '<p>No analytics data available.</p>';
+                return;
+              }
+              // Create a table with Tailwind classes
+              let tableHTML = '<div class="overflow-x-auto"><table class="min-w-full bg-white border border-gray-200"><thead><tr>';
+              tableHTML += '<th class="px-4 py-2 border">Short URL</th>';
+              tableHTML += '<th class="px-4 py-2 border">Original URL</th>';
+              tableHTML += '<th class="px-4 py-2 border">Total Visits</th>';
+              tableHTML += '<th class="px-4 py-2 border">Visit Timestamps</th>';
+              tableHTML += '</tr></thead><tbody>';
+              data.analytics.forEach(item => {
+                tableHTML += '<tr>';
+                tableHTML += '<td class="px-4 py-2 border"><a class="text-blue-500 underline" target="_blank" href="' + item.shortUrl + '">' + item.shortUrl + '</a></td>';
+                tableHTML += '<td class="px-4 py-2 border">' + item.originalUrl + '</td>';
+                tableHTML += '<td class="px-4 py-2 border">' + item.totalVisits + '</td>';
+                tableHTML += '<td class="px-4 py-2 border">' + (item.visitTimestamps.length ? item.visitTimestamps.join(', ') : 'N/A') + '</td>';
+                tableHTML += '</tr>';
+              });
+              tableHTML += '</tbody></table></div>';
+            
+              analyticsSection.innerHTML = tableHTML;
+            } else {
+              analyticsSection.innerHTML = '<p>Error fetching analytics.</p>';
+            }
+          } catch (err) {
+            analyticsSection.innerHTML = '<p>Error connecting to server.</p>';
+          }
+        });
+      </script>
+    </body>
+    </html>
+  `);
+});
+
+// API Endpoint to shorten a URL
+app.post("/shorten", (req, res) => {
+  const { url } = req.body;
+
+  // Validate URL format
+  try {
+    new URL(url);
+  } catch (e) {
+    return res.status(400).json({ error: "Invalid URL provided" });
+  }
+
+  // Generate a unique short code
+  const code = nanoid(7);
+
+  // Store URL and an empty analytics visits array
+  urlDatabase[code] = {
+    originalURL: url,
+    visits: [],
+  };
+
+  // Return the shortened URL information
+  res.status(201).json({
+    shortCode: code,
+    shortUrl: `${baseUrl}/${code}`,
+    originalUrl: url,
+  });
+});
+
+// Endpoint to redirect short URLs to the original URL
+app.get("/:code", (req, res) => {
+  const { code } = req.params;
+  const record = urlDatabase[code];
+
+  if (!record) {
+    return res.status(404).json({ error: "Short URL not found" });
+  }
+
+  // Record analytics with the current timestamp
+  record.visits.push(new Date().toISOString());
+
+  // Perform a redirect to the original URL
+  res.redirect(record.originalURL);
+});
+
+// Endpoint to provide analytics data on usage
+app.get("/analytics", (req, res) => {
+  const analytics = Object.entries(urlDatabase).map(([code, data]) => ({
+    shortCode: code,
+    shortUrl: `${baseUrl}/${code}`,
+    originalUrl: data.originalURL,
+    totalVisits: data.visits.length,
+    visitTimestamps: data.visits,
+  }));
+
+  res.json({ analytics });
+});
+
+// Start the server
+app.listen(port, () => {
+  console.log(`URL Shortening service with UI is running on ${baseUrl}`);
+});
+
+// Export the app for testing or further use if needed
+module.exports = app;
+```
+
+Explanation:
+
+• We now serve an HTML page at the root ("/") that uses Tailwind CSS for a modern, responsive design.  
+• The page contains an input field to submit a URL, a button to invoke the API via fetch, and displays the shortened URL with a clickable link.  
+• An additional "Usage Analytics" section features a button which fetches all analytics data and renders it in a table.  
+• The backend endpoints (/shorten, /:code, and /analytics) operate as before, with the UI built on top to create an overall polished experience.
+
+This self-contained file is the complete solution. Enjoy your enhanced URL shortening service with a polished user interface!
