+                const description = document.getElementById('main-description');
+                
+                // Stagger the animations
+                setTimeout(() => {
+                    title.classList.add('fade-in');
+                }, 500); // Slight delay for the title
+                
+                setTimeout(() => {
+                    description.classList.add('fade-in');
+                }, 800); // Longer delay for the description
+            }
+
+            // Additional interactive effects
+            function addHoverEffects() {
+                const title = document.getElementById('main-title');
+                const description = document.getElementById('main-description');
+                
+                // Subtle scale effect on hover
+                [title, description].forEach(el => {
+                    el.addEventListener('mouseenter', (e) => {
+                        e.target.style.transform = 'scale(1.05)';
+                    });
+                    
+                    el.addEventListener('mouseleave', (e) => {
+                        e.target.style.transform = 'scale(1)';
+                    });
+                });
+            }
+
+            // Run animations and hover effects
+            animateElements();
+            addHoverEffects();
+
+            // Optional: Animate background video brightness on page load
+            const video = document.querySelector('video');
+            video.style.filter = 'brightness(0.7)';
+            video.style.transition = 'filter 1.5s ease';
+        });
+    </script>
+</body>
+</html>
+```
+
