+Here's an enhanced version of the layout builder that supports multiple named layouts:
+
+```jsx
+// App.jsx
+import React, { useState, useEffect } from 'react';
+import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';
+import styled from 'styled-components';
+
+const componentList = {
+  header: { id: 'header', type: 'Header', content: 'Header Component' },
+  text: { id: 'text', type: 'Text', content: 'Text Component' },
+  button: { id: 'button', type: 'Button', content: 'Button Component' },
+  image: { id: 'image', type: 'Image', content: 'Image Component' },
+};
+
+// Styled components
+const Container = styled.div`
+  display: flex;
+  gap: 20px;
+  padding: 20px;
+`;
+
+const SidePanel = styled.div`
+  width: 250px;
+  padding: 10px;
+  background: #f0f0f0;
+  border-radius: 5px;
+`;
+
+const Canvas = styled.div`
+  flex-grow: 1;
+  min-height: 500px;
+  padding: 20px;
+  background: #ffffff;
+  border: 1px solid #ccc;
+  border-radius: 5px;
+`;
+
+const DraggableItem = styled.div`
+  padding: 10px;
+  margin: 5px 0;
+  background: white;
+  border: 1px solid #ddd;
+  border-radius: 3px;
+  cursor: pointer;
+`;
+
+const SavedLayout = styled.div`
+  padding: 10px;
+  margin: 5px 0;
+  background: white;
+  border: 1px solid #ddd;
+  border-radius: 3px;
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+`;
+
+const SaveForm = styled.div`
+  margin-top: 20px;
+  padding: 10px;
+  border-top: 1px solid #ddd;
+`;
+
+const Button = styled.button`
+  padding: 5px 10px;
+  margin: 2px;
+  border-radius: 3px;
+  border: 1px solid #ddd;
+  background: ${props => props.primary ? '#4CAF50' : 'white'};
+  color: ${props => props.primary ? 'white' : 'black'};
+  cursor: pointer;
+`;
+
+function App() {
+  const [layout, setLayout] = useState([]);
+  const [layouts, setLayouts] = useState({});
+  const [layoutName, setLayoutName] = useState('');
+  const [selectedLayout, setSelectedLayout] = useState(null);
+
+  // Load saved layouts on component mount
+  useEffect(() => {
+    const savedLayouts = localStorage.getItem('savedLayouts');
+    if (savedLayouts) {
+      setLayouts(JSON.parse(savedLayouts));
+    }
+  }, []);
+
+  const onDragEnd = (result) => {
+    if (!result.destination) return;
+
+    const { source, destination } = result;
+
+    if (source.droppableId === 'components' && destination.droppableId === 'canvas') {
+      const component = componentList[result.draggableId];
+      const newComponent = {
+        ...component,
+        id: `${component.id}-${Date.now()}`,
+      };
+
+      setLayout(prevLayout => {
+        const newLayout = Array.from(prevLayout);
+        newLayout.splice(destination.index, 0, newComponent);
+        return newLayout;
+      });
+    }
+
+    if (source.droppableId === 'canvas' && destination.droppableId === 'canvas') {
+      setLayout(prevLayout => {
+        const newLayout = Array.from(prevLayout);
+        const [removed] = newLayout.splice(source.index, 1);
+        newLayout.splice(destination.index, 0, removed);
+        return newLayout;
+      });
+    }
+  };
+
+  const saveLayout = () => {
+    if (!layoutName.trim()) {
+      alert('Please enter a layout name');
+      return;
+    }
+
+    const newLayouts = {
+      ...layouts,
+      [layoutName]: layout
+    };
+
+    setLayouts(newLayouts);
+    localStorage.setItem('savedLayouts', JSON.stringify(newLayouts));
+    setLayoutName('');
+    alert('Layout saved!');
+  };
+
+  const loadLayout = (name) => {
+    setLayout(layouts[name]);
+    setSelectedLayout(name);
+  };
+
+  const deleteLayout = (name) => {
+    const newLayouts = { ...layouts };
+    delete newLayouts[name];
+    setLayouts(newLayouts);
+    localStorage.setItem('savedLayouts', JSON.stringify(newLayouts));
+    if (selectedLayout === name) {
+      setSelectedLayout(null);
+      setLayout([]);
+    }
+  };
+
+  const createNewLayout = () => {
+    setLayout([]);
+    setSelectedLayout(null);
+  };
+
+  return (
+    <div>
+      <h1>Layout Builder</h1>
+      <Button primary onClick={createNewLayout}>New Layout</Button>
+      <Container>
+        <DragDropContext onDragEnd={onDragEnd}>
+          <SidePanel>
+            <h3>Components</h3>
+            <Droppable droppableId="components" isDropDisabled={true}>
+              {(provided) => (
+                <div {...provided.droppableProps} ref={provided.innerRef}>
+                  {Object.values(componentList).map((component, index) => (
+                    <Draggable
+                      key={component.id}
+                      draggableId={component.id}
+                      index={index}
+                    >
+                      {(provided) => (
+                        <DraggableItem
+                          ref={provided.innerRef}
+                          {...provided.draggableProps}
+                          {...provided.dragHandleProps}
+                        >
+                          {component.type}
+                        </DraggableItem>
+                      )}
+                    </Draggable>
+                  ))}
+                  {provided.placeholder}
+                </div>
+              )}
+            </Droppable>
+
+            <SaveForm>
+              <h3>Save Layout</h3>
+              <input
+                type="text"
+                value={layoutName}
+                onChange={(e) => setLayoutName(e.target.value)}
+                placeholder="Enter layout name"
+              />
+              <Button primary onClick={saveLayout}>Save</Button>
+            </SaveForm>
+
