+### Implementation:
+Below is the complete Java code for the expanded functionality:
+
+```java
+import java.util.Random;
+import java.util.Scanner;
+
+public class SmartGridWithRenewables {
+
+    // Simulated sensor data
+    static class SensorData {
+        int demand; // Power demand in MW
+        int conventionalSupply; // Power supply from conventional sources in MW
+        int solarSupply; // Power supply from solar in MW
+        int windSupply; // Power supply from wind in MW
+        String gridCondition; // Conditions like "Stable", "Overloaded", "Underloaded"
+
+        public SensorData(int demand, int conventionalSupply, int solarSupply, int windSupply, String gridCondition) {
+            this.demand = demand;
+            this.conventionalSupply = conventionalSupply;
+            this.solarSupply = solarSupply;
+            this.windSupply = windSupply;
+            this.gridCondition = gridCondition;
+        }
+
+        // Calculate total supply (conventional + renewable)
+        public int getTotalSupply() {
+            return conventionalSupply + solarSupply + windSupply;
+        }
+    }
+
+    // Simulated grid manager
+    static class GridManager {
+        private SensorData sensorData;
+
+        public GridManager() {
+            // Initialize with default values
+            this.sensorData = new SensorData(100, 80, 10, 10, "Stable");
+        }
+
+        // Simulate collecting data from sensors
+        public void collectSensorData() {
+            Random random = new Random();
+
+            int demand = 80 + random.nextInt(40); // Random demand between 80 and 120 MW
+            int solarSupply = 10 + random.nextInt(20); // Random solar supply between 10 and 30 MW
+            int windSupply = 15 + random.nextInt(20); // Random wind supply between 15 and 35 MW
+            int conventionalSupply = 90 + random.nextInt(30); // Random conventional supply between 90 and 120 MW
+
+            String condition;
+            int totalSupply = solarSupply + windSupply + conventionalSupply;
+
+            if (totalSupply < demand) {
+                condition = "Overloaded";
+            } else if (totalSupply > demand + 20) {
+                condition = "Underloaded";
+            } else {
+                condition = "Stable";
+            }
+
+            this.sensorData = new SensorData(demand, conventionalSupply, solarSupply, windSupply, condition);
+        }
+
+        // Optimize the grid by adjusting conventional supply
+        public void optimizeGrid() {
+            int totalRenewable = sensorData.solarSupply + sensorData.windSupply;
+            int requiredConventional = sensorData.demand - totalRenewable;
+
+            if (requiredConventional < 0) {
+                // Excess renewable energy
+                sensorData.conventionalSupply = 0;
+                sensorData.gridCondition = "Stable";
+            } else {
+                // Adjust conventional supply to meet demand
+                sensorData.conventionalSupply = requiredConventional;
+                sensorData.gridCondition = "Stable";
+            }
+        }
+
+        // Display current grid status
+        public void displayStatus() {
+            System.out.println("Current Grid Status:");
+            System.out.println("Demand: " + sensorData.demand + " MW");
+            System.out.println("Solar Supply: " + sensorData.solarSupply + " MW");
+            System.out.println("Wind Supply: " + sensorData.windSupply + " MW");
+            System.out.println("Conventional Supply: " + sensorData.conventionalSupply + " MW");
+            System.out.println("Total Supply: " + sensorData.getTotalSupply() + " MW");
+            System.out.println("Condition: " + sensorData.gridCondition);
+        }
+    }
+
+    public static void main(String[] args) {
+        GridManager gridManager = new GridManager();
+        Scanner scanner = new Scanner(System.in);
