+            System.out.println("2. Optimize Grid");
+            System.out.println("3. Display Grid Status");
+            System.out.println("4. Exit");
+
+            System.out.print("Enter your choice: ");
+            int choice = scanner.nextInt();
+
+            switch (choice) {
+                case 1:
+                    gridManager.collectSensorData();
+                    System.out.println("Sensor data collected.");
+                    break;
+                case 2:
+                    gridManager.optimizeGrid();
+                    System.out.println("Grid optimized based on renewable energy and demand.");
+                    break;
+                case 3:
+                    gridManager.displayStatus();
+                    break;
+                case 4:
+                    running = false;
+                    System.out.println("Exiting the system. Goodbye!");
+                    break;
+                default:
+                    System.out.println("Invalid choice. Please try again.");
+            }
+        }
+
+        scanner.close();
+    }
+}
