+**Explanation**  
+This C++ program demonstrates how to build one or more sample binary trees, perform a level-order (breadth-first) traversal on each, and then print each tree’s node values level by level. Below is a summary of the steps:  
+1. We define aTreeNode struct to represent nodes in the binary tree.  
+2. Two separate functions buildSampleTree1() and buildSampleTree2() create different sample trees in-memory. All values are hard-coded.  
+3. The printLevelOrder function performs a level-order traversal using a standard library queue to process nodes in FIFO order. Each level is printed on a separate line, with space-separated node values.  
+4. In main(), we create two test trees and call printLevelOrder on each to showcase correct functionality.  
+5. This solution is complete, self-contained, and uses no external libraries beyond the C++ standard library. It does not require user input; all data is embedded.  
+6. The time complexity of the level-order traversal is O(n) for a tree with n nodes, since each node is processed exactly once.  
+7. The program will terminate naturally after printing results for both test trees, requiring no additional user interaction.
+
+```cpp
+#include <iostream>
+#include <queue>
+#include <vector>
+
+using namespace std;
+
+// Definition of a binary tree node
+struct TreeNode {
+    int val;
+    TreeNode* left;
+    TreeNode* right;
+    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
+};
+
+// Builds a sample binary tree with nodes [1, 2, 3, 4, 5].
+//
+// Structure:
+//         1
+//        / \
+//       2   3
+//      / \
+//     4   5
+TreeNode* buildSampleTree1() {
+    TreeNode* root = new TreeNode(1);
+    root->left = new TreeNode(2);
+    root->right = new TreeNode(3);
+    root->left->left = new TreeNode(4);
+    root->left->right = new TreeNode(5);
+    return root;
+}
+
+// Builds another sample binary tree with nodes [10, 11, 12, 13, 14].
+//
+// Structure:
+//         10
+//        /  \
+//       11  12
+//       / \
+//     13   14
+TreeNode* buildSampleTree2() {
+    TreeNode* root = new TreeNode(10);
+    root->left = new TreeNode(11);
+    root->right = new TreeNode(12);
+    root->left->left = new TreeNode(13);
+    root->left->right = new TreeNode(14);
+    return root;
+}
+
+// Prints the binary tree level by level (breadth-first traversal).
+// Uses a queue from the standard library for FIFO processing.
+void printLevelOrder(TreeNode* root) {
+    if (!root) {
+        return; // No tree to print
+    }
+    queue<TreeNode*> nodeQueue;
+    nodeQueue.push(root);
+
+    // Process until the queue is empty
+    while (!nodeQueue.empty()) {
+        int levelSize = nodeQueue.size(); // Number of nodes in the current level
+
+        // Process each node in the current level
+        for (int i = 0; i < levelSize; ++i) {
+            TreeNode* current = nodeQueue.front();
+            nodeQueue.pop();
+
+            // Print the node's value; keep them space-separated
+            cout << current->val;
+            if (i < levelSize - 1) {
+                cout << " ";
+            }
+
+            // Enqueue child nodes if they exist
+            if (current->left) nodeQueue.push(current->left);
+            if (current->right) nodeQueue.push(current->right);
+        }
+        // Move to the next line after printing a level
+        cout << "\n";
+    }
+}
+
+int main() {
+    // Test Case 1
+    TreeNode* sampleTree1 = buildSampleTree1();
+    cout << "Level-order traversal of first sample tree:\n";
+    printLevelOrder(sampleTree1);
+    cout << "\n";
+
+    // Test Case 2
+    TreeNode* sampleTree2 = buildSampleTree2();
+    cout << "Level-order traversal of second sample tree:\n";
+    printLevelOrder(sampleTree2);
+    cout << "\n";
+
+    // Cleanup of allocated memory is omitted for brevity in this demo code.
+    // End of program - no user interaction required.
+    return 0;
+}
+```
