+The idea behind this approach is that as you iterate through the array you keep track of the “best” (highest) product achieved so far. However, because multiplying by a negative number can flip the largest product into a smallest product (and vice versa), you must keep track of both the maximum and minimum products ending at each element. Then at each position you update the current maximum by picking the higher product (comparing the current number, the product of the current number and the previous maximum, and the product of the current number and the previous minimum).
+
+Below is a complete, self‑contained React component written in JavaScript with Tailwind CSS for styling. You can paste this code into your React project and run it directly.
+
+```javascript
+import React, { useState } from "react";
+
+function MaxProductSubarray() {
+  const [inputValue, setInputValue] = useState("2,3,-2,4");
+  const [result, setResult] = useState(null);
+  const [error, setError] = useState("");
+
+  // Function that calculates the maximum product subarray
+  const calculateMaxProduct = (nums) => {
+    if (nums.length === 0) return { maxProduct: 0, subarray: [] };
+
+    // Using the approach: at every element, choose the best product so far.
+    let currMax = nums[0];
+    let currMin = nums[0];
+    let globalMax = nums[0];
+    // Track indices for the best subarray
+    let start = 0, end = 0, tempStart = 0;
+
+    for (let i = 1; i < nums.length; i++) {
+      // When a negative number is encountered, swap the current max and min
+      // because a negative times a minimum (which might be negative) may become maximum.
+      if (nums[i] < 0) {
+        [currMax, currMin] = [currMin, currMax];
+      }
+
+      // Update the maximum product ending at the current position:
+      // either starting a new subarray at i or extending the previous subarray.
+      if (nums[i] > currMax * nums[i]) {
+        currMax = nums[i];
+        tempStart = i; // start a new subarray
+      } else {
+        currMax = currMax * nums[i];
+      }
+
+      // Similarly update the current minimum product.
+      currMin = Math.min(nums[i], currMin * nums[i]);
+
+      // If the current maximum product is the best we've seen, update the global maximum
+      if (currMax > globalMax) {
+        globalMax = currMax;
+        start = tempStart;
+        end = i;
+      }
+    }
+
+    return { maxProduct: globalMax, subarray: nums.slice(start, end + 1) };
+  };
+
+  const handleCalculate = (e) => {
+    e.preventDefault();
+    setError("");
+    try {
+      // Parse input: "2,3,-2,4" into [2, 3, -2, 4]
+      const nums = inputValue
+        .split(",")
+        .map((s) => s.trim())
+        .filter((s) => s !== "")
+        .map((s) => {
+          const num = Number(s);
+          if (isNaN(num)) {
+            throw new Error("Please enter only numbers separated by commas.");
+          }
+          return num;
+        });
+      if (nums.length === 0) {
+        throw new Error("The array cannot be empty.");
+      }
+      const result = calculateMaxProduct(nums);
+      setResult(result);
+    } catch (err) {
+      setError(err.message);
+      setResult(null);
+    }
+  };
+
+  return (
+    <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
+      <div className="bg-white shadow-md rounded-lg p-6 w-full max-w-md">
+        <h1 className="text-2xl font-bold text-gray-800 mb-4">
+          Maximum Product Subarray Calculator
+        </h1>
+        <form onSubmit={handleCalculate}>
+          <label className="block text-gray-700 mb-2">
+            Enter numbers (comma separated):
+          </label>
+          <input
+            type="text"
+            value={inputValue}
+            onChange={(e) => setInputValue(e.target.value)}
+            className="w-full p-2 border border-gray-300 rounded mb-4"
+            placeholder="e.g., 2,3,-2,4"
+          />
+          <button
+            type="submit"
+            className="w-full bg-blue-500 text-white p-2 rounded hover:bg-blue-600 transition duration-200"
+          >
+            Calculate
+          </button>
+        </form>
+        {error && (
+          <div className="mt-4 text-red-600">
+            {error}
+          </div>
+        )}
+        {result && (
+          <div className="mt-4 text-gray-800">
+            <p>
+              <span className="font-semibold">Max Product:</span> {result.maxProduct}
+            </p>
+            <p className="mt-2">
+              <span className="font-semibold">Subarray:</span> {JSON.stringify(result.subarray)}
+            </p>
+          </div>
+        )}
+      </div>
+    </div>
+  );
+}
+
+export default MaxProductSubarray;
+```
+
+Explanation:
+1. We parse the user’s comma‑separated input to form an array of numbers.
+2. In the calculateMaxProduct function, for each element we:
+   - Swap the current maximum and minimum when a negative number is encountered.
+   - Compute the new current maximum by checking whether starting fresh at the current element is better or continuing the multiplication.
+   - Update the global maximum if the current maximum exceeds it.
+3. Finally, the component displays both the maximum product found and the corresponding subarray.
+
