+Below is a complete React component written in JavaScript that uses Highcharts (with Highstocks and the annotations module) to simulate stock market data and let users annotate the chart by clicking on it. Users click the "Enter Annotation Mode" button to enable annotation mode. Then, when they click anywhere on the chart, a prompt will ask for annotation text and a new annotation will be added at the clicked point. This improves the user experience by allowing users to mark significant events on the chart.
+
+Before running the code, install the necessary packages with:
+npm install highcharts highcharts-react-official
+
+Below is the single-file code:
+
+--------------------------------------------------
+
+```jsx
+import React, { useState, useRef, useEffect } from "react";
+import Highcharts from "highcharts/highstock";
+import HighchartsReact from "highcharts-react-official";
+import AnnotationsModule from "highcharts/modules/annotations";
+
+// Initialize the annotations module
+AnnotationsModule(Highcharts);
+
+// Utility function to simulate stock data for 50 days.
+const generateStockData = () => {
+  const dataPoints = [];
+  const volumePoints = [];
+  const smaPoints = [];
+  const oneDay = 24 * 3600 * 1000;
+  const now = new Date();
+  const startTime = now.getTime() - 50 * oneDay;
+  let price = 100; // base price
+
+  for (let i = 0; i < 50; i++) {
+    const time = startTime + i * oneDay;
+    price = price + (Math.random() * 4 - 2); // simulate price change between -2 and +2
+    const roundedPrice = Math.round(price * 100) / 100;
+    dataPoints.push([time, roundedPrice]);
+    // Simulate trading volume between 1000 and 5000
+    const volume = Math.floor(Math.random() * 4000 + 1000);
+    volumePoints.push([time, volume]);
+  }
+
+  // Compute 5-day Simple Moving Average (SMA)
+  for (let i = 0; i < dataPoints.length; i++) {
+    if (i < 4) {
+      smaPoints.push([dataPoints[i][0], null]);
+    } else {
+      let sum = 0;
+      for (let j = i - 4; j <= i; j++) {
+        sum += dataPoints[j][1];
+      }
+      const sma = Math.round((sum / 5) * 100) / 100;
+      smaPoints.push([dataPoints[i][0], sma]);
+    }
+  }
+
+  return { priceData: dataPoints, volumeData: volumePoints, smaData: smaPoints };
+};
+
+const FinancialDashboard = () => {
+  const [stockData, setStockData] = useState({
+    priceData: [],
+    volumeData: [],
+    smaData: []
+  });
+  // Track if annotation mode is active.
+  const [annotationMode, setAnnotationMode] = useState(false);
+  // Reference to the Highcharts chart instance.
+  const chartRef = useRef(null);
+
+  useEffect(() => {
+    const data = generateStockData();
+    setStockData(data);
+  }, []);
+
+  // Highcharts configuration
+  const options = {
+    chart: {
+      zoomType: "x",
+      events: {
+        click: function (event) {
+          // Only add annotation if we're in annotation mode.
+          if (!annotationMode) return;
+          // Retrieve clicked x and y values (for the primary yAxis).
+          const x = event.xAxis[0].value;
+          const y = event.yAxis[0].value;
+          const text = prompt("Enter annotation text", "Significant Event");
+          if (text !== null) {
+            // Add annotation at the clicked point.
+            this.addAnnotation({
+              labels: [
+                {
+                  point: {
+                    xAxis: 0,
+                    yAxis: 0,
+                    x: x,
+                    y: y
+                  },
+                  text: text
+                }
+              ],
+              // Optionally, you could add shapes or adjust styling here.
+              visible: true
+            });
+          }
+          // Disable annotation mode after a click.
+          setAnnotationMode(false);
+        }
+      }
+    },
+    title: {
+      text: "Financial Dashboard: Stock Market Data"
+    },
+    rangeSelector: {
+      selected: 1,
+      inputEnabled: false
+    },
+    xAxis: {
+      type: "datetime"
+    },
+    yAxis: [
+      {
+        labels: {
+          align: "right",
+          x: -3
+        },
+        title: {
+          text: "Price"
+        },
+        height: "65%",
+        lineWidth: 2,
+        resize: {
+          enabled: true
+        }
+      },
+      {
+        labels: {
+          align: "right",
+          x: -3
+        },
+        title: {
+          text: "Volume"
+        },
+        top: "70%",
+        height: "25%",
+        offset: 0,
+        lineWidth: 2
+      }
+    ],
+    tooltip: {
+      shared: true
+    },
+    series: [
+      {
+        type: "line",
+        name: "Price",
+        data: stockData.priceData,
+        tooltip: {
+          valueDecimals: 2
+        },
+        color: "#1D4ED8" // Tailwind blue-700
+      },
+      {
+        type: "line",
+        name: "5-day SMA",
+        data: stockData.smaData,
+        tooltip: {
+          valueDecimals: 2
+        },
+        color: "#F59E0B" // Tailwind amber-500
+      },
+      {
+        type: "column",
+        name: "Volume",
+        data: stockData.volumeData,
+        yAxis: 1,
+        tooltip: {
+          valueDecimals: 0
+        },
+        color: "#10B981" // Tailwind green-500
+      }
+    ],
+    credits: {
+      enabled: false
+    }
+  };
+
+  return (
+    <div className="p-4 bg-gray-50 min-h-screen">
+      <h1 className="text-2xl font-bold text-center text-gray-800 mb-4">
+        Financial Dashboard
+      </h1>
+      <div className="mb-4 text-center">
+        <button
+          className="bg-blue-600 hover:bg-blue-700 text-white font-medium py-2 px-4 rounded"
+          onClick={() => setAnnotationMode(true)}
+        >
+          Enter Annotation Mode
+        </button>
+        {annotationMode && (
+          <span className="ml-4 text-sm text-gray-700">
+            Click on the chart to add an annotation.
+          </span>
+        )}
+      </div>
+      <div className="shadow-lg border rounded">
+        <HighchartsReact
+          highcharts={Highcharts}
+          constructorType="stockChart"
+          options={options}
+          ref={chartRef}
+        />
+      </div>
+    </div>
+  );
