+```python
+import streamlit as st
+import os
+from datetime import datetime
+
+ATTENDANCE_FILE = "attendance_records.txt"
+
+def load_attendance():
+    """
+    Loads attendance records from a file.
+    Each record is stored as a dictionary with keys "Name" and "Timestamp".
+    """
+    records = []
+    if os.path.exists(ATTENDANCE_FILE):
+        with open(ATTENDANCE_FILE, "r") as f:
+            for line in f:
+                line = line.strip()
+                if line:  # skip empty lines
+                    parts = line.split(",")
+                    if len(parts) >= 2:
+                        name = parts[0].strip()
+                        timestamp = parts[1].strip()
+                        records.append({"Name": name, "Timestamp": timestamp})
+    return records
+
+def add_attendance(name):
+    """
+    Records the attendance by appending a new entry to the file.
+    The entry includes the student name and the current timestamp.
+    """
+    if name:
+        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
+        with open(ATTENDANCE_FILE, "a") as f:
+            f.write(f"{name},{timestamp}\n")
+        st.success(f"Recorded attendance for '{name}' at {timestamp}")
+
+# Inject custom CSS for a polished UI
+st.markdown(
+    """
+    <style>
+    /* Overall background and font */
