+    th {
+        background-color: #f1f5f9;
+        color: #1f2937;
+        font-weight: 600;
+    }
+    </style>
+    """, unsafe_allow_html=True)
+
+# App title and description
+st.markdown('<div class="main-header">Classroom Attendance Manager</div>', unsafe_allow_html=True)
+st.markdown('<div class="subheader">Enter a student\'s name below to record their attendance:</div>', unsafe_allow_html=True)
+
+# Input for student's name
+name_input = st.text_input("Student Name")
