+# Button to add attendance record
+if st.button("Record Attendance"):
+    add_attendance(name_input)
+    st.experimental_rerun()  # Refresh the app to update records
+
+# Display all attendance records in a table
+records = load_attendance()
+if records:
+    st.markdown("### Attendance Records")
+    st.table(records)
+else:
+    st.info("No attendance records found.")
+
