+      const eventDate = parseISO(event.date);
+      const diffTime = eventDate - today;
+      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
+      return diffDays > 0 && diffDays <= 7;
+    });
+    setReminders(upcoming);
+  }, [events]);
+
+  const renderHeader = () => {
