+Below is a complete, self-contained Node.js program that implements a command-line Hangman game. It uses the npm packages "random-words" and "prompt-sync" to select random words and read user input from the terminal. Install them by running:  
+• npm install random-words prompt-sync
+
+Explanation of the solution:
+1. The game generates a random word from the "random-words" library.
+2. The program keeps track of correct guesses, missed guesses, and the number of allowed attempts.
+3. On each turn, the program displays the current state of the hidden word and prompts the player for a letter. 
+4. If the guess is correct, it updates the guessed letters; if incorrect, it reduces the number of attempts left.
+5. The game ends either when the user runs out of attempts or successfully guesses the entire word.
+
+```javascript
+// To run this code:
+// 1. npm install random-words prompt-sync
+// 2. node hangman.js
+
+const randomWords = require("random-words");
+const prompt = require("prompt-sync")();
+
+// Number of attempts allowed
+const MAX_ATTEMPTS = 6;
+
+function displayProgress(secretWord, guessedLetters) {
+  let display = "";
+  for (const letter of secretWord) {
+    if (guessedLetters.has(letter)) {
+      display += letter + " ";
+    } else {
+      display += "_ ";
+    }
+  }
+  return display.trim();
+}
+
+function hasWon(secretWord, guessedLetters) {
+  for (const letter of secretWord) {
+    if (!guessedLetters.has(letter)) {
+      return false;
+    }
+  }
+  return true;
+}
+
+function hangman() {
+  const randomWord = randomWords(); // Generate a random word
+  const secretWord = randomWord.toLowerCase();
+
+  let attemptsRemaining = MAX_ATTEMPTS;
+  const guessedLetters = new Set();
+
+  console.log("Welcome to Hangman!");
+  console.log(
+    `A random word has been chosen. You have ${attemptsRemaining} attempts to guess it.`
+  );
+
+  // Main game loop
+  while (attemptsRemaining > 0) {
+    console.log(`\nWord: ${displayProgress(secretWord, guessedLetters)}`);
+    console.log(`Attempts Left: ${attemptsRemaining}`);
+
+    const guess = prompt("Guess a letter: ").toLowerCase();
+
+    if (!guess || guess.length !== 1) {
+      console.log("Please enter a single letter.");
+      continue;
+    }
+
+    if (guessedLetters.has(guess)) {
+      console.log(`You've already guessed "${guess}". Try a different letter.`);
+      continue;
+    }
+
+    guessedLetters.add(guess);
+
+    if (secretWord.includes(guess)) {
+      console.log(`Good job! The letter "${guess}" is in the word.`);
+    } else {
+      attemptsRemaining--;
+      console.log(`Oops! The letter "${guess}" is NOT in the word.`);
+    }
+
+    // Check if the player has guessed all letters
+    if (hasWon(secretWord, guessedLetters)) {
+      console.log(`\nCongratulations! You guessed the word "${secretWord}"`);
+      return;
+    }
+  }
+
+  // If the loop ends, player is out of attempts
+  console.log(
+    `\nGame Over! You ran out of attempts. The word was "${secretWord}".`
+  );
+}
+
+// Start the game
+hangman();
+```
