+To enhance the user experience, we can add a visual indicator that shows the swipe direction (left or right). We'll use a simple text-based indicator that updates dynamically each time a swipe is detected. This will help users understand the direction of their swipe gestures.
+
+Here is the updated code with the visual swipe direction indicator:
+
+```javascript
+import React, { useState, useEffect } from "react";
+
+const SwipeNavigator = () => {
+  const [currentSection, setCurrentSection] = useState(0);
+  const [swipeDirection, setSwipeDirection] = useState(""); // To display swipe direction
+  const sections = ["Section 1", "Section 2", "Section 3"]; // Example sections
+  let touchStartX = 0;
+  let touchEndX = 0;
+
+  const handleSwipe = () => {
+    if (touchStartX - touchEndX > 50) {
+      // Swipe left
+      if (currentSection < sections.length - 1) {
+        setCurrentSection((prev) => prev + 1);
+      }
+      setSwipeDirection("Left");
+    } else if (touchEndX - touchStartX > 50) {
+      // Swipe right
+      if (currentSection > 0) {
+        setCurrentSection((prev) => prev - 1);
+      }
+      setSwipeDirection("Right");
+    } else {
+      setSwipeDirection(""); // No swipe detected
+    }
+  };
+
+  useEffect(() => {
+    const handleTouchStart = (e) => {
+      touchStartX = e.touches[0].clientX;
+    };
+
+    const handleTouchEnd = (e) => {
+      touchEndX = e.changedTouches[0].clientX;
+      handleSwipe();
+    };
+
+    window.addEventListener("touchstart", handleTouchStart);
+    window.addEventListener("touchend", handleTouchEnd);
+
+    return () => {
+      window.removeEventListener("touchstart", handleTouchStart);
+      window.removeEventListener("touchend", handleTouchEnd);
+    };
+  }, [currentSection]);
+
+  return (
+    <div className="flex flex-col items-center justify-center h-screen bg-blue-100">
+      <div className="text-2xl font-bold mb-4">{sections[currentSection]}</div>
+      <div className="text-gray-700 mb-4">
+        Swipe left or right to navigate between sections.
+      </div>
+      <div
+        className={`text-lg font-semibold ${
+          swipeDirection === "Left" ? "text-red-500" : "text-green-500"
+        }`}
+      >
+        {swipeDirection && `Swiped ${swipeDirection}`}
+      </div>
+    </div>
+  );
+};
+
+export default SwipeNavigator;
+```
+
+### New Features Added:
+1. **Swipe Direction Indicator**:
+   - A new state `swipeDirection` is used to store the current swipe direction (`"Left"` or `"Right"`).
+   - This state updates dynamically each time a swipe gesture is detected.
