+### E-commerce Product Listing Page with Shopping Cart using Vue.js
+#### Overview
+The following code creates a simple e-commerce product listing page with a shopping cart feature using Vue.js. It fetches a list of products from a mock API, allows users to filter products by category, sort them by price or rating, add products to their cart, and proceed to checkout.
+
+#### Code
+```javascript
+<template>
+  <div class="p-4">
+    <h1 class="text-3xl mb-4">Product Listing</h1>
+    <div class="flex justify-between mb-4">
+      <select v-model="selectedCategory" class="px-4 py-2 border border-gray-300 rounded">
+        <option value="">All Categories</option>
+        <option v-for="category in categories" :key="category" :value="category">{{ category }}</option>
+      </select>
+      <select v-model="sortBy" class="px-4 py-2 border border-gray-300 rounded">
+        <option value="price">Price (Low to High)</option>
+        <option value="rating">Rating (High to Low)</option>
+      </select>
+    </div>
+    <ul>
+      <li v-for="product in filteredProducts" :key="product.id" class="mb-4">
+        <h2 class="text-2xl">{{ product.name }}</h2>
+        <p>Price: ${{ product.price }}</p>
+        <p>Rating: {{ product.rating }} / 5</p>
+        <button @click="addToCart(product)" class="bg-green-500 hover:bg-green-700 text-white font-bold py-2 px-4 rounded">Add to Cart</button>
+      </li>
+    </ul>
+    <div class="fixed bottom-0 right-0 p-4 bg-gray-200 border border-gray-300 rounded">
+      <h2 class="text-2xl mb-2">Cart</h2>
+      <ul>
+        <li v-for="product in cart" :key="product.id" class="mb-2">
+          {{ product.name }} x {{ product.quantity }} = ${{ product.price * product.quantity }}
+          <button @click="removeFromCart(product)" class="bg-red-500 hover:bg-red-700 text-white font-bold py-1 px-2 rounded">Remove</button>
+        </li>
+      </ul>
+      <p>Total: ${{ total }}</p>
+      <button @click="checkout" class="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded">Checkout</button>
+    </div>
+  </div>
+</template>
+
+<script>
+import axios from 'axios';
+
+export default {
+  data() {
+    return {
+      products: [],
+      categories: [],
+      selectedCategory: '',
+      sortBy: 'price',
+      cart: [],
+    };
+  },
+  async mounted() {
+    const response = await axios.get('https://jsonplaceholder.typicode.com/posts');
+    this.products = response.data.map((product, index) => ({
+      id: index,
+      name: product.title,
+      price: Math.floor(Math.random() * 100),
+      rating: Math.floor(Math.random() * 5),
+      category: ['Electronics', 'Fashion', 'Home Goods'][Math.floor(Math.random() * 3)],
+    }));
+    this.categories = [...new Set(this.products.map(product => product.category))];
+  },
+  computed: {
+    filteredProducts() {
+      return this.products.filter(product => product.category === this.selectedCategory || this.selectedCategory === '')
+        .sort((a, b) => {
+          if (this.sortBy === 'price') {
+            return a.price - b.price;
+          } else {
+            return b.rating - a.rating;
+          }
+        });
+    },
+    total() {
+      return this.cart.reduce((acc, product) => acc + product.price * product.quantity, 0);
+    },
+  },
+  methods: {
+    addToCart(product) {
+      const existingProduct = this.cart.find(p => p.id === product.id);
+      if (existingProduct) {
+        existingProduct.quantity++;
+      } else {
+        this.cart.push({ ...product, quantity: 1 });
+      }
+    },
+    removeFromCart(product) {
+      const index = this.cart.findIndex(p => p.id === product.id);
+      if (index !== -1) {
+        if (this.cart[index].quantity > 1) {
+          this.cart[index].quantity--;
+        } else {
+          this.cart.splice(index, 1);
+        }
+      }
+    },
+    checkout() {
+      alert(`Checkout successful! Total: $${this.total}`);
+      this.cart = [];
+    },
+  },
+};
+</script>
+
+<style scoped>
+/* Add some basic styling */
+ul {
+  list-style: none;
+  padding: 0;
+  margin: 0;
+}
+li {
+  background-color: #f7f7f7;
+  padding: 20px;
+  border: 1px solid #ddd;
+  border-radius: 10px;
+  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
+}
+</style>
+```
