+// Function to find the k closest elements to the target in a sorted array
+std::vector<int> findKClosestElements(const std::vector<int>& arr, int k, int target) {
+    int n = arr.size();
+    int left = 0, right = n - 1;
+    
+    // Binary search to locate the closest element to the target
+    while (left < right) {
+        int mid = left + (right - left) / 2;
+        if (arr[mid] < target) {
+            left = mid + 1;
+        } else {
+            right = mid;
+        }
+    }
+    
+    // Initialize two pointers around the closest element found
+    int closest = left; // 'left' now points to the closest element
+    left = closest - 1;
+    right = closest;
+    
+    // Collect k closest elements using two pointers
+    std::vector<int> result;
+    while (k > 0) {
+        if (left >= 0 && right < n) {
+            if (std::abs(arr[left] - target) <= std::abs(arr[right] - target)) {
+                result.push_back(arr[left]);
+                --left;
+            } else {
+                result.push_back(arr[right]);
+                ++right;
+            }
+        } else if (left >= 0) { // Only the left pointer is valid
+            result.push_back(arr[left]);
+            --left;
+        } else if (right < n) { // Only the right pointer is valid
+            result.push_back(arr[right]);
+            ++right;
+        }
+        --k;
+    }
+    
+    // Sort the result for ascending order
+    std::sort(result.begin(), result.end());
+    return result;
