+To add a feature where the entire cloth can be moved with the mouse, we need to slightly adjust the interaction logic. Specifically, we will allow users to "grab" the cloth and drag it around. This involves detecting when the user clicks on a point and, while dragging, updating all the points' positions relative to the mouse movement.
+
+Below is the updated code with the added feature:
+
+```javascript
+<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>Interactive Cloth Simulation</title>
+  <style>
+    body {
+      margin: 0;
+      overflow: hidden;
+    }
+    canvas {
+      display: block;
+    }
+  </style>
+</head>
+<body>
+  <canvas id="clothCanvas"></canvas>
+  <script>
+    const canvas = document.getElementById('clothCanvas');
+    const ctx = canvas.getContext('2d');
+
+    // Resize canvas to fit the window
+    canvas.width = window.innerWidth;
+    canvas.height = window.innerHeight;
+
+    const gravity = 0.5;
+    const friction = 0.99;
+    const mouse = { x: 0, y: 0, isDown: false, dragOffsetX: 0, dragOffsetY: 0 };
+
+    let isDraggingCloth = false;
+
+    class Point {
+      constructor(x, y, isPinned = false) {
+        this.x = x;
+        this.y = y;
+        this.oldX = x;
+        this.oldY = y;
+        this.isPinned = isPinned;
+      }
+
+      update() {
+        if (this.isPinned) return;
+
+        const velocityX = (this.x - this.oldX) * friction;
+        const velocityY = (this.y - this.oldY) * friction;
+
+        this.oldX = this.x;
+        this.oldY = this.y;
+
+        this.x += velocityX;
+        this.y += velocityY + gravity;
+
+        // Constrain within canvas boundaries
+        if (this.x < 0) this.x = 0;
+        if (this.x > canvas.width) this.x = canvas.width;
+        if (this.y > canvas.height) this.y = canvas.height;
+      }
+
+      applyForce(dx, dy) {
+        if (this.isPinned) return;
+
+        this.oldX -= dx;
+        this.oldY -= dy;
+      }
+
+      move(dx, dy) {
+        this.x += dx;
+        this.y += dy;
+        this.oldX += dx;
+        this.oldY += dy;
+      }
+    }
+
+    class Stick {
+      constructor(p1, p2, length) {
+        this.p1 = p1;
+        this.p2 = p2;
+        this.length = length;
+      }
+
+      update() {
+        const dx = this.p2.x - this.p1.x;
+        const dy = this.p2.y - this.p1.y;
+        const distance = Math.sqrt(dx * dx + dy * dy);
+        const difference = this.length - distance;
+        const percent = difference / distance / 2;
+        const offsetX = dx * percent;
+        const offsetY = dy * percent;
+
+        if (!this.p1.isPinned) {
+          this.p1.x -= offsetX;
+          this.p1.y -= offsetY;
+        }
+        if (!this.p2.isPinned) {
+          this.p2.x += offsetX;
+          this.p2.y += offsetY;
+        }
+      }
+
+      draw() {
+        ctx.beginPath();
+        ctx.moveTo(this.p1.x, this.p1.y);
+        ctx.lineTo(this.p2.x, this.p2.y);
+        ctx.strokeStyle = '#444';
+        ctx.stroke();
+      }
+    }
+
+    class Cloth {
+      constructor(width, height, spacing, startX, startY) {
+        this.points = [];
+        this.sticks = [];
+
+        for (let y = 0; y < height; y++) {
+          for (let x = 0; x < width; x++) {
+            const isPinned = y === 0; // Pin the top row
+            const point = new Point(startX + x * spacing, startY + y * spacing, isPinned);
+            this.points.push(point);
+
+            // Horizontal stick
+            if (x > 0) {
+              const stick = new Stick(point, this.points[this.points.length - 2], spacing);
+              this.sticks.push(stick);
+            }
+
+            // Vertical stick
+            if (y > 0) {
+              const stick = new Stick(point, this.points[(y - 1) * width + x], spacing);
+              this.sticks.push(stick);
+            }
+          }
+        }
+      }
+
+      update() {
+        this.points.forEach(point => point.update());
+        for (let i = 0; i < 5; i++) { // Iterative constraint solving
+          this.sticks.forEach(stick => stick.update());
+        }
+      }
+
+      draw() {
+        this.sticks.forEach(stick => stick.draw());
+      }
+
+      move(dx, dy) {
+        this.points.forEach(point => {
+          if (!point.isPinned) {
+            point.move(dx, dy);
+          }
+        });
+      }
+    }
+
+    const cloth = new Cloth(40, 30, 15, canvas.width / 4, canvas.height / 5);
+
+    function animate() {
+      ctx.clearRect(0, 0, canvas.width, canvas.height);
+      cloth.update();
+      cloth.draw();
+      requestAnimationFrame(animate);
+    }
+
+    canvas.addEventListener('mousedown', (e) => {
+      mouse.isDown = true;
+      mouse.x = e.clientX;
+      mouse.y = e.clientY;
+
+      // Check if user clicks near the cloth
+      cloth.points.forEach(point => {
+        const dx = mouse.x - point.x;
+        const dy = mouse.y - point.y;
+        const distance = Math.sqrt(dx * dx + dy * dy);
+
+        if (distance < 20) {
+          isDraggingCloth = true;
+          mouse.dragOffsetX = dx;
+          mouse.dragOffsetY = dy;
+        }
+      });
+    });
+
+    canvas.addEventListener('mousemove', (e) => {
+      if (!mouse.isDown) return;
+
+      const dx = e.clientX - mouse.x;
+      const dy = e.clientY - mouse.y;
+
+      mouse.x = e.clientX;
+      mouse.y = e.clientY;
+
+      if (isDraggingCloth) {
+        cloth.move(dx, dy);
+      } else {
+        // Apply forces to points near the mouse
+        cloth.points.forEach(point => {
+          const dx = mouse.x - point.x;
+          const dy = mouse.y - point.y;
+          const distance = Math.sqrt(dx * dx + dy * dy);
+
+          if (distance < 20) {
+            point.applyForce(dx * 0.1, dy * 0.1);
+          }
+        });
+      }
+    });
+
+    canvas.addEventListener('mouseup', () => {
+      mouse.isDown = false;
+      isDraggingCloth = false;
+    });
+
+    animate();
+  </script>
+</body>
+</html>
+```
+
+### What Changed?
+1. **Dragging the Cloth**:
+   - Added logic to detect if the user is clicking near the cloth points.
+   - If the click is near a point, treat it as dragging the cloth.
+   - Move all points of the cloth by the mouse movement (`dx`, `dy`) when dragging.
+
+2. **Mouse Interaction**:
+   - Differentiated between dragging the entire cloth and applying forces to points.
+   - Used a new flag `isDraggingCloth` to track if the user is moving the cloth.
+
+### Features of Updated Code:
+- Users can now move the entire cloth by clicking and dragging near any part of it.
+- Users can still interact with individual points by clicking and dragging near them.
+- The cloth retains its realistic physics behavior.
