+Below is a complete React component written in JavaScript that implements an interactive typing speed test with your requested new features. In this version, an array of sentences is defined. When the user finishes typing the current sentence correctly before the timer runs out, a notice is displayed along with a button to load another sentence. The timer is also stopped immediately when the sentence is completed. Tailwind CSS is used for styling. This entire component is self-contained in a single file and ready to run!
+
+Explanation:
+
+1. We define a list of sentences and randomly choose one when starting.
+2. The component tracks user input, the timer, and whether the sentence is completed.
+3. As soon as the user starts typing, the timer is started.
+4. When the user input exactly matches the target sentence, it prevents further typing, stops the timer, and displays a success notice along with a "Next Sentence" button.
+5. Clicking the "Next Sentence" button picks a new sentence from the list (randomly), resets the timer and input state, and allows the user to start over.
+
+Below is the complete code:
+
+```javascript
+import React, { useState, useEffect, useRef } from "react";
+
+const SENTENCES = [
+  "The quick brown fox jumps over the lazy dog.",
+  "Lorem ipsum dolor sit amet, consectetur adipiscing elit.",
+  "Pack my box with five dozen liquor jugs.",
+  "How vexingly quick daft zebras jump!"
+];
+
+const TOTAL_TIME = 30; // seconds
+
+const TypingSpeedTest = () => {
+  const [currentSentence, setCurrentSentence] = useState(() => {
+    return SENTENCES[Math.floor(Math.random() * SENTENCES.length)];
+  });
+  const [userInput, setUserInput] = useState("");
+  const [timeLeft, setTimeLeft] = useState(TOTAL_TIME);
+  const [isStarted, setIsStarted] = useState(false);
+  const [isCompleted, setIsCompleted] = useState(false);
+  const timerRef = useRef(null);
+
+  // Start the timer when test starts
+  useEffect(() => {
+    if (isStarted && timeLeft > 0 && !isCompleted) {
+      timerRef.current = setInterval(() => {
+        setTimeLeft((prevTime) => prevTime - 1);
+      }, 1000);
+    }
+    return () => clearInterval(timerRef.current);
+  }, [isStarted, timeLeft, isCompleted]);
+
+  // Stop timer when time is up
+  useEffect(() => {
+    if (timeLeft === 0) {
+      clearInterval(timerRef.current);
+    }
+  }, [timeLeft]);
+
+  // If user finishes the current sentence successfully, mark as complete and stop the timer.
+  useEffect(() => {
+    if (userInput === currentSentence && userInput !== "") {
+      setIsCompleted(true);
+      clearInterval(timerRef.current);
+    }
+  }, [userInput, currentSentence]);
+
+  const handleInputChange = (e) => {
+    const value = e.target.value;
+    if (!isStarted) {
+      setIsStarted(true);
+    }
+    if(!isCompleted){
+      setUserInput(value);
+    }
+  };
+
+  const calculateResults = () => {
+    let correctChars = 0;
+    for (let i = 0; i < userInput.length; i++) {
+      if (userInput[i] === currentSentence[i]) {
+        correctChars++;
+      }
+    }
+    const timeSpent = TOTAL_TIME - timeLeft || 1;
+    const wpm = Math.round((correctChars / 5) / (timeSpent / 60));
+    return { correctChars, wpm };
+  };
+
+  const results = (timeLeft === 0 || isCompleted) ? calculateResults() : null;
+
+  const chooseNextSentence = () => {
+    const nextSentence = SENTENCES[Math.floor(Math.random() * SENTENCES.length)];
+    setCurrentSentence(nextSentence);
+    setUserInput("");
+    setTimeLeft(TOTAL_TIME);
+    setIsStarted(false);
+    setIsCompleted(false);
+    clearInterval(timerRef.current);
+  };
+
+  return (
+    <div className="min-h-screen flex flex-col items-center justify-center bg-gray-100 p-4">
+      <h1 className="text-3xl font-bold text-gray-800 mb-4">
+        Typing Speed Test
+      </h1>
+      <div className="bg-white shadow-md rounded p-6 max-w-2xl w-full">
+        <p className="text-lg text-gray-700 mb-4">
+          {currentSentence.split("").map((char, index) => {
+            let className = "text-gray-700";
+            if (index < userInput.length) {
+              className = userInput[index] === char ? "text-green-500" : "text-red-500";
+            }
+            return (
+              <span key={index} className={className}>
+                {char}
+              </span>
+            );
+          })}
+        </p>
+        <textarea
+          value={userInput}
+          onChange={handleInputChange}
+          placeholder="Start typing here..."
+          disabled={timeLeft === 0 || isCompleted}
+          className="w-full p-3 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-400 h-32 resize-none"
+        />
+        <div className="flex justify-between items-center mt-4">
+          <span className="text-xl font-semibold text-gray-800">
+            Time Left: {timeLeft}s
+          </span>
+          {(timeLeft === 0 || isCompleted) && (
+            <div className="text-right">
+              {isCompleted && (
+                <p className="text-lg font-bold text-blue-600">Sentence Completed!</p>
+              )}
+              {!isCompleted && timeLeft === 0 && (
+                <p className="text-lg font-bold text-red-600">Time is up!</p>
+              )}
+              <p className="text-lg text-gray-800">
+                Correct Characters: {results.correctChars}
+              </p>
+              <p className="text-lg text-gray-800">
+                Words Per Minute: {results.wpm}
+              </p>
+            </div>
+          )}
+        </div>
+        {(timeLeft === 0 || isCompleted) && (
+          <div className="mt-6 flex justify-center">
+            <button
+              onClick={chooseNextSentence}
+              className="bg-green-500 hover:bg-green-600 text-white font-semibold py-2 px-4 rounded"
+            >
+              Next Sentence
+            </button>
+          </div>
+        )}
+      </div>
+    </div>
+  );
+};
+
+export default TypingSpeedTest;
+```
+
+When you run this code in your React application, you'll have an interactive typing speed test that shows a notice when the user finishes the sentence and allows them to choose a new sentence by clicking the "Next Sentence" button. Enjoy testing your typing speed!
