+Below is a complete Node.js program that runs an Express server with a polished UI. The UI (built with Tailwind CSS from the CDN) lets you paste CSV data into a textarea, then hit a button to generate a chart. The server uses the csv-parser library to parse the CSV input and chartjs-node-canvas (a Chart.js wrapper) to produce a PNG image of a bar chart, which is then displayed on the page.
+
+Before running this code, install the dependencies by executing:
+npm install express chartjs-node-canvas csv-parser
+
+Below is the full, self-contained code:
+
+```javascript
+// Run "npm install express chartjs-node-canvas csv-parser" before executing this code.
+
+const express = require("express");
+const bodyParser = require("body-parser");
+const csvParser = require("csv-parser");
+const { Readable } = require("stream");
+const { ChartJSNodeCanvas } = require("chartjs-node-canvas");
+
+const app = express();
+const port = 3000;
+
+// Middleware to parse JSON and URL-encoded data
+app.use(bodyParser.json());
+app.use(bodyParser.urlencoded({ extended: true }));
+
+// Function that takes a CSV string and returns a Promise that resolves with an object containing labels and values arrays.
+function parseCSVData(csvString) {
+  return new Promise((resolve, reject) => {
+    const labels = [];
+    const values = [];
+
+    const stream = Readable.from(csvString);
+    stream
+      .pipe(csvParser())
+      .on("data", (row) => {
+        // Expecting each row to have "label" and "value" columns.
+        labels.push(row.label);
+        values.push(Number(row.value));
+      })
+      .on("end", () => {
+        resolve({ labels, values });
+      })
+      .on("error", (err) => {
+        reject(err);
+      });
+  });
+}
+
+// Endpoint that serves the main HTML page with the polished UI
+app.get("/", (_req, res) => {
+  const html = `
+  <!DOCTYPE html>
+  <html lang="en">
+  <head>
+    <meta charset="UTF-8" />
+    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
+    <title>CSV Chart Generator</title>
+    <script src="https://cdn.tailwindcss.com"></script>
+  </head>
+  <body class="bg-gray-50 min-h-screen flex items-center justify-center">
+    <div class="container mx-auto p-4">
+      <div class="max-w-xl mx-auto bg-white rounded-xl shadow-md p-6">
+        <h1 class="text-2xl font-bold text-gray-800 mb-4 text-center">CSV Chart Generator</h1>
+        <p class="text-gray-600 mb-4">Paste your CSV data below (make sure it has a header row with "label" and "value"):</p>
+        <textarea id="csvData" rows="8" 
+          class="w-full p-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-green-500"
+        >label,value
+January,30
+February,20
+March,50
+April,40
+May,60
+        </textarea>
+        <button id="generateBtn" 
+          class="mt-4 bg-green-500 hover:bg-green-600 text-white font-semibold py-2 px-4 rounded w-full">
+          Generate Chart
+        </button>
+        <div id="chartContainer" class="mt-6 flex flex-col items-center">
+          <!-- The generated chart will appear here -->
+        </div>
+      </div>
+    </div>
+
+    <script>
+      const generateBtn = document.getElementById("generateBtn");
+      const chartContainer = document.getElementById("chartContainer");
+
+      generateBtn.addEventListener("click", async () => {
+        // Clear previous chart (if any)
+        chartContainer.innerHTML = '<p class="text-gray-600 mb-2">Generating chart...</p>';
+
+        const csvData = document.getElementById("csvData").value;
+
+        try {
+          const response = await fetch("/chart", {
+            method: "POST",
+            headers: {
+              "Content-Type": "application/json"
+            },
+            body: JSON.stringify({ csvData })
+          });
+          
+          if (!response.ok) {
+            throw new Error("Chart generation failed.");
+          }
+          const blob = await response.blob();
+          const imageUrl = URL.createObjectURL(blob);
+          
+          chartContainer.innerHTML = "";
+          const img = document.createElement("img");
+          img.src = imageUrl;
+          img.alt = "Generated Chart";
+          img.className = "rounded shadow-md border border-gray-300";
+          chartContainer.appendChild(img);
+        } catch (error) {
+          chartContainer.innerHTML = '<p class="text-red-500">Error generating chart.</p>';
+          console.error(error);
+        }
+      });
+    </script>
+  </body>
+  </html>
+  `;
+  res.send(html);
+});
+
+// Endpoint that accepts CSV data in the request body, generates a chart, and returns the PNG image.
+app.post("/chart", async (req, res) => {
+  try {
+    const { csvData } = req.body;
+    if (!csvData) {
+      return res.status(400).send("CSV data is required.");
+    }
+
+    const { labels, values } = await parseCSVData(csvData);
+
+    // Chart dimensions
+    const width = 800;
+    const height = 600;
+
+    // Create the ChartJSNodeCanvas instance
+    const chartJSNodeCanvas = new ChartJSNodeCanvas({ width, height });
+
+    // Chart configuration (using Tailwind-inspired colors)
+    const configuration = {
+      type: "bar",
+      data: {
+        labels: labels,
+        datasets: [
+          {
+            label: "Monthly Values",
+            data: values,
+            backgroundColor: "rgba(16, 185, 129, 0.6)", // Tailwind green-500 with transparency
+            borderColor: "rgba(16, 185, 129, 1)",
+            borderWidth: 1,
+          },
+        ],
+      },
+      options: {
+        scales: {
+          y: {
+            beginAtZero: true,
+            ticks: {
+              color: "#1F2937" // Tailwind gray-800
+            }
+          },
+          x: {
+            ticks: {
+              color: "#1F2937" // Tailwind gray-800
+            }
+          }
+        },
+        plugins: {
+          legend: {
+            labels: {
+              color: "#1F2937", // Tailwind gray-800
+              font: {
+                size: 14
+              }
+            }
+          }
+        }
+      },
+    };
+
+    // Generate the chart as a PNG image buffer
+    const imageBuffer = await chartJSNodeCanvas.renderToBuffer(configuration);
+
+    res.writeHead(200, {
+      "Content-Type": "image/png",
+      "Content-Length": imageBuffer.length,
+    });
+    res.end(imageBuffer);
+  } catch (error) {
+    console.error("Error generating chart:", error);
+    res.status(500).send("Error generating chart.");
+  }
+});
+
+// Start the server
+app.listen(port, () => {
+  console.log(`Server is running at http://localhost:${port}`);
+});
+```
+
+Explanation:
+
+1. We set up an Express server with body parsing middleware.
+2. The GET "/" endpoint serves an HTML page styled using Tailwind CSS. The page contains a textarea pre-filled with sample CSV data and a "Generate Chart" button.
+3. The client-side JavaScript listens for button clicks, sends the CSV data to the POST "/chart" endpoint (using fetch with JSON), and then displays the returned chart image.
+4. The POST "/chart" endpoint uses csv-parser to read CSV data and chartjs-node-canvas to create a bar chart image from the parsed data. The PNG image is then sent back as the HTTP response.
+5. The server listens on port 3000.
+
+Simply run the program (node filename.js) and visit http://localhost:3000 in your browser to see the polished UI in action.
