+Explanation of the solution:
+Only chips at positions that are perfect squares remain on. This is because each position gets toggled once for every divisor it has, and most non-square numbers have divisors in pairs (leading to an even count and thus ending up off). A perfect square has a divisor (its square root) that does not pair up, giving an odd number of total divisors and thus remains on. The final count of bulbs on is simply the integer part of the square root of n.
+
+Below is a self-contained React component in JavaScript. It shows an input to enter the number of bulbs n, a button to calculate, and outputs which bulbs remain on (i.e., their perfect square positions) as well as the total count of those bulbs.
+
+```javascript
+import React, { useState } from "react";
+
+function PerfectSquareBulbs() {
+  const [n, setN] = useState(0);
+  const [result, setResult] = useState(null);
+  const [positions, setPositions] = useState([]);
+
+  const handleCalculate = () => {
+    const sqrtN = Math.floor(Math.sqrt(n));
+    const bulbsOn = [];
+    for (let i = 1; i <= sqrtN; i++) {
+      bulbsOn.push(i * i);
+    }
+    setResult(sqrtN);
+    setPositions(bulbsOn);
+  };
+
+  return (
+    <div className="flex flex-col items-center p-6 bg-blue-50 min-h-screen">
+      <h1 className="text-2xl font-bold text-blue-800 mb-4">
+        Perfect Square Bulbs
+      </h1>
+      <label className="mb-2 text-black" htmlFor="nInput">
+        Enter number of bulbs (n):
+      </label>
+      <input
+        id="nInput"
+        type="number"
+        className="border border-blue-800 rounded px-2 py-1 mb-4"
+        value={n}
+        onChange={(e) => setN(e.target.valueAsNumber)}
+      />
+      <button
+        className="bg-blue-600 text-white font-semibold px-4 py-2 rounded hover:bg-blue-500 mb-4"
+        onClick={handleCalculate}
+      >
+        Calculate
+      </button>
+      {result !== null && (
+        <div className="text-black">
+          <p className="text-lg font-semibold mb-2">
+            Number of bulbs that remain on: {result}
+          </p>
+          <p>
+            Positions of bulbs on (perfect squares ≤ n): {positions.join(", ")}
+          </p>
+        </div>
+      )}
+    </div>
+  );
+}
+
+export default PerfectSquareBulbs;
+```
