+                    // Show next path if available
+                    if (this.currentIndex < this.history.length - 1) {
+                        this.nextPathDiv.textContent = `Next path: ${this.history[this.currentIndex + 1]}`;
+                        this.nextPathDiv.classList.add('show');
+                    }
+                }
+            }
+
+            goForward() {
+                if (this.currentIndex < this.history.length - 1) {
+                    this.currentIndex++;
+                    this.updatePath(this.history[this.currentIndex]);
+                    this.updateButtonStates();
+                    this.nextPathDiv.classList.remove('show');
+                }
+            }
+
+            updateButtonStates() {
+                this.prevButton.disabled = this.currentIndex <= 0;
+                this.nextButton.disabled = this.currentIndex >= this.history.length - 1;
+            }
+
+            updatePath(path) {
+                this.paths = path.split('/').filter(segment => segment !== '');
+                this.render();
+            }
+
+            render() {
+                this.container.innerHTML = '';
+                let fullPath = '';
+
+                this.paths.forEach((segment, index) => {
+                    fullPath += `/${segment}`;
+                    
+                    const li = document.createElement('li');
+                    li.className = 'breadcrumb-item';
+                    
+                    if (index === this.paths.length - 1) {
+                        li.classList.add('active');
+                    }
+
+                    const a = document.createElement('a');
+                    a.href = '#'; // Using # for demo purposes
+                    a.textContent = this.formatSegment(segment);
+                    a.onclick = (e) => {
+                        e.preventDefault();
+                        this.navigateTo(fullPath);
+                    };
+                    
+                    li.appendChild(a);
+                    this.container.appendChild(li);
+                });
+            }
+
+            formatSegment(segment) {
+                return segment
+                    .split('-')
+                    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
+                    .join(' ');
+            }
+        }
+
+        // Initialize breadcrumb navigator
+        const breadcrumb = new BreadcrumbNavigator('breadcrumbList');
+
+        // Example usage with some test navigation
+        setTimeout(() => {
+            breadcrumb.navigateTo('/home/products/electronics');
+        }, 1000);
+
+        setTimeout(() => {
+            breadcrumb.navigateTo('/home/products/electronics/smartphones');
+        }, 2000);
+    </script>
+</body>
+</html>
+```
