+I'll provide a comprehensive solution that meets all the specified requirements, focusing on efficiency, readability, and completeness.
+
+Analysis and Approach:
+Problem: Find the maximum product of three numbers in an array
+Key Requirements:
+- O(n) time complexity
+- Handle both positive and negative numbers
+- Single-pass algorithm
+- Standalone C++ program
+- Use standard library only
+
+Solution Strategy:
+1. Use a single-pass algorithm to track:
+   - Top 3 largest numbers
+   - Top 2 smallest numbers (for handling negative number scenarios)
+2. Compare two possible maximum products:
+   - Product of 3 largest positive numbers
+   - Product of largest number and 2 smallest numbers
+3. Implement robust error handling
+4. Include multiple test cases
+5. Optimize for performance and readability
+
+```cpp
+#include <iostream>
+#include <vector>
+#include <climits>
+#include <algorithm>
+#include <stdexcept>
+
+class MaxProductFinder {
+private:
+    // Helper method to validate input
+    static void validateInput(const std::vector<int>& nums) {
+        if (nums.size() < 3) {
+            throw std::invalid_argument("Array must contain at least 3 elements");
+        }
+    }
+
+public:
+    // Core algorithm to find maximum product of three numbers
+    static int findMaxProductOfThree(const std::vector<int>& nums) {
+        // Validate input
+        validateInput(nums);
+
+        // Initialize tracking variables
+        int largest = INT_MIN;
+        int secondLargest = INT_MIN;
+        int thirdLargest = INT_MIN;
+        int smallest = INT_MAX;
+        int secondSmallest = INT_MAX;
+
+        // Single pass through the array
+        for (int num : nums) {
+            // Update largest numbers
+            if (num > largest) {
+                thirdLargest = secondLargest;
+                secondLargest = largest;
+                largest = num;
+            } else if (num > secondLargest) {
+                thirdLargest = secondLargest;
+                secondLargest = num;
+            } else if (num > thirdLargest) {
+                thirdLargest = num;
+            }
+
+            // Update smallest numbers
+            if (num < smallest) {
+                secondSmallest = smallest;
+                smallest = num;
+            } else if (num < secondSmallest) {
+                secondSmallest = num;
+            }
+        }
+
+        // Compute two possible max products
+        int maxProduct1 = largest * secondLargest * thirdLargest;
+        int maxProduct2 = largest * smallest * secondSmallest;
+
+        // Return the maximum
+        return std::max(maxProduct1, maxProduct2);
+    }
+
+    // Test method to run multiple scenarios
+    static void runTests() {
+        // Test Case 1: All positive numbers
+        std::vector<int> testCase1 = {1, 2, 3, 4};
+        std::cout << "Test Case 1 (All Positive): " 
+                  << findMaxProductOfThree(testCase1) << std::endl;  // Expected: 24
+
+        // Test Case 2: Mixed positive and negative numbers
+        std::vector<int> testCase2 = {-1, -2, -3, 4, 5};
+        std::cout << "Test Case 2 (Mixed Numbers): " 
+                  << findMaxProductOfThree(testCase2) << std::endl;  // Expected: 60
+
+        // Test Case 3: Negative and zero numbers
+        std::vector<int> testCase3 = {-5, -2, -1, 0, 1, 2};
+        std::cout << "Test Case 3 (Negative & Zero): " 
+                  << findMaxProductOfThree(testCase3) << std::endl;  // Expected: 20
+
+        // Test Case 4: Large numbers
+        std::vector<int> testCase4 = {1000, 500, 200, 100, 50};
+        std::cout << "Test Case 4 (Large Numbers): " 
+                  << findMaxProductOfThree(testCase4) << std::endl;  // Expected: 100,000,000
+    }
+};
+
+int main() {
+    try {
+        // Run test cases
+        MaxProductFinder::runTests();
+    } catch (const std::exception& e) {
+        std::cerr << "Error: " << e.what() << std::endl;
+        return 1;
+    }
+
+    return 0;
+}
+```
+
