+<body>
+    <div class="container">
+        <h1>Event Countdown Timer</h1>
+        
+        <div class="input-container">
+            <input type="datetime-local" id="eventDateTime">
+            <input type="text" id="eventName" placeholder="Event Name">
+            <button onclick="startCountdown()">Start Countdown</button>
+        </div>
+
+        <!-- Error message container -->
+        <div id="errorMessage" class="error-message"></div>
+
+        <div class="countdown">
+            <div class="countdown-item">
+                <div class="countdown-value" id="days">0</div>
+                <div>Days</div>
+            </div>
+            <div class="countdown-item">
+                <div class="countdown-value" id="hours">0</div>
+                <div>Hours</div>
+            </div>
+            <div class="countdown-item">
+                <div class="countdown-value" id="minutes">0</div>
+                <div>Minutes</div>
+            </div>
+            <div class="countdown-item">
+                <div class="countdown-value" id="seconds">0</div>
+                <div>Seconds</div>
+            </div>
