+
+        // Set minimum date-time to current time
+        window.onload = function() {
+            const now = new Date();
+            const year = now.getFullYear();
+            const month = String(now.getMonth() + 1).padStart(2, '0');
+            const day = String(now.getDate()).padStart(2, '0');
+            const hours = String(now.getHours()).padStart(2, '0');
+            const minutes = String(now.getMinutes()).padStart(2, '0');
+            
+            const currentDateTime = `${year}-${month}-${day}T${hours}:${minutes}`;
+            document.getElementById('eventDateTime').min = currentDateTime;
+        }
+
+        function startCountdown() {
+            // Clear any existing countdown
+            if (countdownInterval) {
+                clearInterval(countdownInterval);
+            }
+
+            // Get the input values
+            const eventDateTime = new Date(document.getElementById('eventDateTime').value).getTime();
+            const eventName = document.getElementById('eventName').value || 'Event';
+            const now = new Date().getTime();
+            const errorMessage = document.getElementById('errorMessage');
+
+            // Validate the date
+            if (!document.getElementById('eventDateTime').value) {
+                errorMessage.style.display = 'block';
+                errorMessage.innerHTML = 'Please select a date and time!';
+                return;
+            }
+
+            // Check if the date is in the past
+            if (eventDateTime < now) {
+                errorMessage.style.display = 'block';
+                errorMessage.innerHTML = 'Please select a future date and time!';
+                return;
+            }
+
+            // Clear error message if validation passes
+            errorMessage.style.display = 'none';
+            
+            // Display event name
+            document.getElementById('eventDisplay').innerHTML = `Countdown to: ${eventName}`;
+
+            // Update countdown every second
+            countdownInterval = setInterval(() => {
+                const currentTime = new Date().getTime();
+                const distance = eventDateTime - currentTime;
+
+                // Time calculations
+                const days = Math.floor(distance / (1000 * 60 * 60 * 24));
+                const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
+                const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
+                const seconds = Math.floor((distance % (1000 * 60)) / 1000);
+
+                // Display the results
+                document.getElementById('days').innerHTML = days;
+                document.getElementById('hours').innerHTML = hours;
+                document.getElementById('minutes').innerHTML = minutes;
+                document.getElementById('seconds').innerHTML = seconds;
+
+                // If the countdown is finished
+                if (distance < 0) {
+                    clearInterval(countdownInterval);
+                    document.getElementById('days').innerHTML = "0";
+                    document.getElementById('hours').innerHTML = "0";
+                    document.getElementById('minutes').innerHTML = "0";
+                    document.getElementById('seconds').innerHTML = "0";
+                    alert(`${eventName} time has arrived!`);
+                }
+            }, 1000);
+        }
+    </script>
