+        const seconds = Math.floor((timeDifference % (1000 * 60)) / 1000);
+        
+        countdownDisplay.textContent =
+          days + 'd ' + hours + 'h ' + minutes + 'm ' + seconds + 's';
+      }, 1000);
+    });
+  </script>
+</body>
+</html>
+```
