+
+```jsx
+// App.jsx
+import React, { useState, useEffect } from 'react';
+import './App.css';
+
+const GRID_SIZE = 30;
+const MIN_ROOMS = 6;
+const MAX_ROOMS = 10;
+const MIN_ROOM_SIZE = 4;
+const MAX_ROOM_SIZE = 8;
+
+const TILE_TYPES = {
+  WALL: '🟫',
+  FLOOR: '⬜',
+  PLAYER: '🧙',
+  ENEMY: '👾',
+  TREASURE: '💎',
+};
+
+function createRoom(dungeon, x, y, width, height) {
+  for (let dy = 0; dy < height; dy++) {
+    for (let dx = 0; dx < width; dx++) {
+      if (y + dy < GRID_SIZE && x + dx < GRID_SIZE) {
+        dungeon[y + dy][x + dx] = TILE_TYPES.FLOOR;
+      }
+    }
+  }
+}
+
+function createCorridor(dungeon, x1, y1, x2, y2) {
+  // Create L-shaped corridor
+  const points = [];
+  let currentX = x1;
+  let currentY = y1;
+
+  while (currentX !== x2 || currentY !== y2) {
+    if (Math.random() < 0.5) {
+      if (currentX < x2) currentX++;
+      else if (currentX > x2) currentX--;
+      else if (currentY < y2) currentY++;
+      else if (currentY > y2) currentY--;
+    } else {
+      if (currentY < y2) currentY++;
+      else if (currentY > y2) currentY--;
+      else if (currentX < x2) currentX++;
+      else if (currentX > x2) currentX--;
+    }
+    points.push({ x: currentX, y: currentY });
+  }
+
+  // Create corridor with width of 2
+  points.forEach(point => {
+    for (let dy = -1; dy <= 1; dy++) {
+      for (let dx = -1; dx <= 1; dx++) {
+        const newX = point.x + dx;
+        const newY = point.y + dy;
+        if (newX >= 0 && newX < GRID_SIZE && newY >= 0 && newY < GRID_SIZE) {
+          dungeon[newY][newX] = TILE_TYPES.FLOOR;
+        }
+      }
+    }
+  });
+}
+
+function App() {
+  const [dungeon, setDungeon] = useState([]);
+  const [playerPos, setPlayerPos] = useState({ x: 0, y: 0 });
+  const [score, setScore] = useState(0);
+  const [health, setHealth] = useState(100);
+
+  const generateDungeon = () => {
+    // Initialize empty dungeon with walls
+    let newDungeon = Array(GRID_SIZE).fill().map(() =>
+      Array(GRID_SIZE).fill(TILE_TYPES.WALL)
+    );
+
+    // Generate rooms
+    const rooms = [];
+    let attempts = 0;
+    const maxAttempts = 100;
+
+    while (rooms.length < MIN_ROOMS && attempts < maxAttempts) {
+      const width = MIN_ROOM_SIZE + Math.floor(Math.random() * (MAX_ROOM_SIZE - MIN_ROOM_SIZE));
+      const height = MIN_ROOM_SIZE + Math.floor(Math.random() * (MAX_ROOM_SIZE - MIN_ROOM_SIZE));
+      const x = 1 + Math.floor(Math.random() * (GRID_SIZE - width - 2));
+      const y = 1 + Math.floor(Math.random() * (GRID_SIZE - height - 2));
+
+      // Check if room overlaps with existing rooms
+      let overlaps = false;
+      for (const room of rooms) {
+        if (x < room.x + room.width + 2 &&
+            x + width + 2 > room.x &&
+            y < room.y + room.height + 2 &&
+            y + height + 2 > room.y) {
+          overlaps = true;
+          break;
+        }
+      }
+
+      if (!overlaps) {
+        rooms.push({ x, y, width, height });
+        createRoom(newDungeon, x, y, width, height);
+      }
+      attempts++;
+    }
+
+    // Connect rooms
+    for (let i = 0; i < rooms.length - 1; i++) {
+      const room1 = rooms[i];
+      const room2 = rooms[i + 1];
+      
+      const start = {
+        x: Math.floor(room1.x + room1.width / 2),
+        y: Math.floor(room1.y + room1.height / 2)
+      };
+      
+      const end = {
+        x: Math.floor(room2.x + room2.width / 2),
+        y: Math.floor(room2.y + room2.height / 2)
+      };
+
+      createCorridor(newDungeon, start.x, start.y, end.x, end.y);
+    }
+
+    // Add enemies and treasures
+    let enemyCount = 0;
+    let treasureCount = 0;
+    const maxEnemies = 8;
+    const maxTreasures = 6;
+
+    while (enemyCount < maxEnemies || treasureCount < maxTreasures) {
+      const x = Math.floor(Math.random() * GRID_SIZE);
+      const y = Math.floor(Math.random() * GRID_SIZE);
+      
+      if (newDungeon[y][x] === TILE_TYPES.FLOOR) {
+        if (enemyCount < maxEnemies) {
+          newDungeon[y][x] = TILE_TYPES.ENEMY;
+          enemyCount++;
+        } else if (treasureCount < maxTreasures) {
+          newDungeon[y][x] = TILE_TYPES.TREASURE;
+          treasureCount++;
+        }
+      }
+    }
+
+    // Set player starting position in first room
+    const startRoom = rooms[0];
+    const startX = Math.floor(startRoom.x + startRoom.width / 2);
+    const startY = Math.floor(startRoom.y + startRoom.height / 2);
+    setPlayerPos({ x: startX, y: startY });
+    newDungeon[startY][startX] = TILE_TYPES.PLAYER;
+
+    setDungeon(newDungeon);
+  };
+
+  // Rest of the code remains the same as before...
+  // (movePlayer function and return statement)
+
+  useEffect(() => {
+    generateDungeon();
+  }, []);
+
+  const movePlayer = (dx, dy) => {
