+        return;
+      }
+    } else if (dungeon[newY][newX] === TILE_TYPES.TREASURE) {
+      setScore(prev => prev + 10);
+    }
+
+    newDungeon[playerPos.y][playerPos.x] = TILE_TYPES.FLOOR;
+    newDungeon[newY][newX] = TILE_TYPES.PLAYER;
+    setDungeon(newDungeon);
+    setPlayerPos({ x: newX, y: newY });
