+      while (currentEnemyHealth > 0 && currentHealth > 0) {
+        currentEnemyHealth -= playerAttack;
+        currentHealth -= enemyAttack;
+      }
+      if (currentHealth > 0) {
+        setPlayerHealth(currentHealth);
+        setPlayerInventory([...playerInventory, 'Sword']);
+        setHint('You defeated an enemy!');
+      } else {
+        alert('Game Over');
+      }
+    } else if (dungeon[playerPosition[0]][playerPosition[1]] === 5) {
+      // Collect treasure
+      setPlayerInventory([...playerInventory, 'Treasure']);
+      setHint('You found a treasure!');
+    } else if (dungeon[playerPosition[0]][playerPosition[1]] === 3) {
+      setHint('You encountered an obstacle. Try moving around it.');
+    } else {
+      setHint('');
+    }
+  };
+
+  // Provide hints
+  useEffect(() => {
+    if (playerPosition[0] < dungeon.length - 1 && dungeon[playerPosition[0] + 1][playerPosition[1]] === 4) {
+      setHint('There is an enemy below you. Be careful!');
+    } else if (playerPosition[0] > 0 && dungeon[playerPosition[0] - 1][playerPosition[1]] === 4) {
+      setHint('There is an enemy above you. Be careful!');
+    } else if (playerPosition[1] < dungeon[0].length - 1 && dungeon[playerPosition[0]][playerPosition[1] + 1] === 4) {
+      setHint('There is an enemy to your right. Be careful!');
+    } else if (playerPosition[1] > 0 && dungeon[playerPosition[0]][playerPosition[1] - 1] === 4) {
+      setHint('There is an enemy to your left. Be careful!');
+    }
+  }, [playerPosition, dungeon]);
+
+  return (
+    <div className="p-4">
+      <h1 className="text-2xl font-bold mb-4">Procedurally Generated Dungeon Game</h1>
+      <div className="flex flex-col mb-4">
+        {drawDungeon(dungeon, playerPosition)}
+      </div>
+      <div className="flex justify-around mb-4">
+        <button
+          className="px-4 py-2 bg-blue-500 text-white rounded"
+          onClick={() => handleMove('up')}
+        >
+          Up
+        </button>
+        <button
+          className="px-4 py-2 bg-blue-500 text-white rounded"
+          onClick={() => handleMove('down')}
+        >
+          Down
+        </button>
+        <button
+          className="px-4 py-2 bg-blue-500 text-white rounded"
+          onClick={() => handleMove('left')}
+        >
+          Left
+        </button>
+        <button
+          className="px-4 py-2 bg-blue-500 text-white rounded"
+          onClick={() => handleMove('right')}
+        >
+          Right
+        </button>
+      </div>
+      <div className="flex flex-col mb-4">
+        <p>Player Health: {playerHealth}</p>
+        <p>Player Inventory: {playerInventory.join(', ')}</p>
+        <p>Hint: {hint}</p>
