+Below is a complete React component that fetches random jokes from the Official Joke API and displays them in a polished UI using Tailwind CSS classes. This code is self-contained in a single file. Simply import it into your React project. (Make sure you have installed the "axios" package with npm install axios)
+
+Explanation:
+• We use React with useState to manage our joke data, loading state, and potential errors.
+• When the button is clicked, the fetchJoke function fetches a new random joke from the public API.
+• Tailwind CSS classes are applied for a modern, polished look.
+
+Here is the complete code:
+
+```javascript
+import React, { useState } from 'react';
+import axios from 'axios';
+
+const JokeApp = () => {
+  const [joke, setJoke] = useState(null);
+  const [loading, setLoading] = useState(false);
+  const [error, setError] = useState(null);
+
+  const fetchJoke = async () => {
+    setLoading(true);
+    setError(null);
+    try {
+      const response = await axios.get('https://official-joke-api.appspot.com/random_joke');
+      setJoke(response.data);
+    } catch (err) {
+      setError('Could not fetch a joke. Please try again.');
+    }
+    setLoading(false);
+  };
+
+  return (
+    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
+      <div className="bg-white shadow-md rounded-lg p-6 max-w-md w-full">
+        <h1 className="text-2xl font-bold mb-4 text-center text-gray-800">
+          Random Joke Generator
+        </h1>
+        {loading && <p className="text-blue-500 text-center mb-4">Loading...</p>}
+        {error && <p className="text-red-500 text-center mb-4">{error}</p>}
+        {joke && !loading && !error && (
+          <div className="mb-4">
+            <p className="text-gray-700 mb-2">
+              <span className="font-semibold">Setup:</span> {joke.setup}
+            </p>
+            <p className="text-gray-700">
+              <span className="font-semibold">Punchline:</span> {joke.punchline}
+            </p>
+          </div>
+        )}
+        <button
+          onClick={fetchJoke}
+          className="w-full bg-blue-500 hover:bg-blue-600 transition-colors text-white py-2 px-4 rounded"
+        >
+          {joke ? 'Get Another Joke' : 'Get a Joke'}
+        </button>
+      </div>
+    </div>
+  );
+};
+
+export default JokeApp;
+```
+
+This component provides a polished UI using Tailwind CSS classes. You can now integrate it into your project, and it will display a random joke when the button is clicked. Enjoy!
