+
+// Function to add thousands separators to a number string
+void format_number(unsigned long long num, char* formatted) {
+    char temp[50] = {0};
+    sprintf(temp, "%llu", num);
+    
+    int len = strlen(temp);
+    int comma_count = (len - 1) / 3;
+    int formatted_index = 0;
+    int temp_index = 0;
+
+    // Add commas from right to left
+    for (int i = len - 1; i >= 0; i--) {
+        formatted[formatted_index++] = temp[temp_index++];
+        
+        // Add comma every 3 digits, but not at the start
+        if ((len - i) % 3 == 0 && i > 0) {
+            formatted[formatted_index++] = ',';
+        }
+    }
+    formatted[formatted_index] = '\0';
+}
+
+// Function to calculate factorial using long long
+unsigned long long factorial(int n) {
+    if (n < 0) return 0;  // Invalid input
+    if (n == 0 || n == 1) return 1;
+
+    unsigned long long result = 1;
+    for (int i = 2; i <= n; i++) {
