+        // Only print if no overflow occurred
+        if (fact > 0) {
+            char formatted_fact[100] = {0};
+            format_number(fact, formatted_fact);
+            printf("%6d | %26s\n", i, formatted_fact);
+        }
+    }
+
+    return 0;
+}
