+```javascript
+import React, { useState, useEffect } from "react";
+import { MapContainer, TileLayer, Marker, Polyline } from "react-leaflet";
+import * as turf from "@turf/turf";
+import "leaflet/dist/leaflet.css";
+
+// Helper function to simulate IoT sensor data
+const generateBinsData = (numBins) => {
+  const bins = [];
+  for (let i = 0; i < numBins; i++) {
+    bins.push({
+      id: i + 1,
+      location: [
+        37.7749 + Math.random() * 0.02 - 0.01, // Random latitude near San Francisco
+        -122.4194 + Math.random() * 0.02 - 0.01, // Random longitude near San Francisco
+      ],
+      fillLevel: Math.floor(Math.random() * 100), // Random fill level between 0-100%
+    });
+  }
+  return bins;
+};
+
+// Route optimization function using Turf.js
+const optimizeRoute = (bins) => {
+  const highPriorityBins = bins
+    .filter((bin) => bin.fillLevel > 75) // Only consider bins with > 75% fill
+    .map((bin) => turf.point(bin.location));
+
+  if (highPriorityBins.length === 0) return [];
+
+  const startPoint = turf.point([37.7749, -122.4194]); // Starting point (e.g., waste collection HQ)
+  const route = [startPoint];
+
+  let remainingBins = highPriorityBins;
+  while (remainingBins.length > 0) {
+    const currentPoint = route[route.length - 1];
+    let nearest = null;
+    let nearestDistance = Infinity;
+
+    remainingBins.forEach((bin, index) => {
+      const distance = turf.distance(currentPoint, bin);
+      if (distance < nearestDistance) {
+        nearest = index;
+        nearestDistance = distance;
+      }
+    });
+
+    route.push(remainingBins[nearest]);
+    remainingBins.splice(nearest, 1);
+  }
+
+  return route.map((point) => point.geometry.coordinates);
+};
+
+const WasteCollectionApp = () => {
