+Explanation:
+In this React component, we extend the previous typing button effect by also animating an underline that grows from left to right in sync with the text. When the user hovers on the button, the text is cleared, and letters are appended one by one at set intervals. For each letter typed, we compute the current underline width (as a percentage of the total label length) and render it as a colored bar below the text. On mouse leave, we cancel the animation and immediately restore the full text and underline.
+
+Below is the complete, self-contained code. You can run this single-file React code in your sandbox environment.
+
+```jsx
+import React, { useState, useRef } from "react";
+
+const TypingButton = () => {
+  const label = "Click Me";
+  const [displayText, setDisplayText] = useState(label);
+  const intervalRef = useRef(null);
+
+  const handleMouseEnter = () => {
+    clearInterval(intervalRef.current);
+    setDisplayText(""); // start with an empty label on hover
+    let index = 0;
+    intervalRef.current = setInterval(() => {
+      setDisplayText((prevText) => {
+        const nextChar = label.charAt(index);
+        index++;
+        // When all characters have been typed, stop the interval.
+        if (index >= label.length) {
+          clearInterval(intervalRef.current);
+        }
+        return prevText + nextChar;
+      });
+    }, 150); // Adjust typing speed (milliseconds)
+  };
+
+  const handleMouseLeave = () => {
+    clearInterval(intervalRef.current);
+    setDisplayText(label); // reset instantly to full label on mouse leave
+  };
+
+  // Calculate underline width as a percentage of the full label.
+  const underlineWidth = `${(displayText.length / label.length) * 100}%`;
+
+  return (
+    <button
+      onMouseEnter={handleMouseEnter}
+      onMouseLeave={handleMouseLeave}
+      className="flex flex-col items-center bg-blue-600 hover:bg-blue-700 text-white font-medium py-2 px-4 rounded transition-colors duration-200"
+    >
+      {/* Display the animated text */}
+      <span>{displayText}</span>
+      {/* Underline element that grows with the text */}
+      <div
+        className="bg-white h-1 mt-1 transition-all duration-150"
+        style={{ width: underlineWidth }}
+      ></div>
+    </button>
+  );
+};
+
+export default TypingButton;
+```
+
+How it works:
+1. Initially, the button displays the full label "Click Me" with a full-width underline.
+2. On mouse enter, the text is cleared and then typed out letter by letter. Simultaneously, the underline width is computed based on the number of letters displayed.
+3. On mouse leave, the animation is canceled and the button instantly goes back to showing the full label and underline.
