+### Optimized Java Text File Analyzer
+
+Below is the optimized Java program that analyzes text files, counts words and characters, identifies the most frequent words, and provides a search functionality. The program uses a simple command-line interface (CLI) for interaction.
+
+```java
+import java.io.FileWriter;
+import java.io.IOException;
+import java.nio.file.Files;
+import java.nio.file.Paths;
+import java.util.HashMap;
+import java.util.Map;
+import java.util.Scanner;
+import java.util.stream.Stream;
+
+public class TextFileAnalyzer {
+
+    public static void main(String[] args) {
+        // Create a sample text file
+        String fileName = "sample.txt";
+        String content = "This is a sample text file. It contains multiple lines of text. The text file analyzer will analyze this file and provide statistics.";
+        createFile(fileName, content);
+
+        // Load the text file
+        String text = readFile(fileName);
+
+        if (text == null || text.isEmpty()) {
+            System.out.println("The file is empty.");
+            return;
+        }
+
+        // Count words and characters
+        int wordCount = countWords(text);
+        int characterCount = countCharacters(text);
+
+        // Identify most frequent words
+        Map<String, Integer> wordFrequencies = countWordFrequencies(text);
+
+        // Print statistics
+        System.out.println("Text File Analyzer");
+        System.out.println("--------------------");
+        System.out.println("Word Count: " + wordCount);
+        System.out.println("Character Count: " + characterCount);
+        System.out.println("Most Frequent Words:");
+        printWordFrequencies(wordFrequencies);
+
+        // Search functionality
+        Scanner scanner = new Scanner(System.in);
+        System.out.print("Enter a word to search: ");
+        String searchWord = scanner.nextLine();
+        int occurrences = searchWord(text, searchWord);
+        if (occurrences == 0) {
+            System.out.println("The word '" + searchWord + "' is not found in the file.");
+        } else {
+            System.out.println("The word '" + searchWord + "' appears " + occurrences + " times.");
+        }
+
+        // Export results
+        exportResults(fileName, wordCount, characterCount, wordFrequencies);
+    }
+
+    // Create a sample text file
+    private static void createFile(String fileName, String content) {
+        try (FileWriter writer = new FileWriter(fileName)) {
+            writer.write(content);
+        } catch (IOException e) {
+            System.err.println("Error creating file: " + e.getMessage());
+        }
+    }
+
+    // Load the text file
+    private static String readFile(String fileName) {
+        try {
+            return Files.readString(Paths.get(fileName));
+        } catch (IOException e) {
+            System.err.println("Error reading file: " + e.getMessage());
+            return null;
+        }
+    }
+
+    // Count words
+    private static int countWords(String text) {
+        return text.split("\\W+").length;
+    }
+
+    // Count characters
+    private static int countCharacters(String text) {
+        return text.length();
+    }
+
+    // Count word frequencies
+    private static Map<String, Integer> countWordFrequencies(String text) {
+        Map<String, Integer> wordFrequencies = new HashMap<>();
+        String[] words = text.toLowerCase().split("\\W+");
+        for (String word : words) {
+            if (!word.isEmpty()) {
+                wordFrequencies.put(word, wordFrequencies.getOrDefault(word, 0) + 1);
+            }
+        }
+        return wordFrequencies;
+    }
+
+    // Print word frequencies
+    private static void printWordFrequencies(Map<String, Integer> wordFrequencies) {
+        wordFrequencies.entrySet().stream()
+                .sorted((e1, e2) -> e2.getValue().compareTo(e1.getValue()))
+                .limit(10)
+                .forEach(entry -> System.out.println(entry.getKey() + ": " + entry.getValue()));
+    }
+
+    // Search for a word
+    private static int searchWord(String text, String word) {
+        String[] words = text.toLowerCase().split("\\W+");
+        int occurrences = 0;
+        for (String w : words) {
+            if (w.equals(word.toLowerCase())) {
+                occurrences++;
+            }
+        }
+        return occurrences;
+    }
+
+    // Export results
+    private static void exportResults(String fileName, int wordCount, int characterCount, Map<String, Integer> wordFrequencies) {
+        try (FileWriter writer = new FileWriter("results.txt")) {
+            StringBuilder results = new StringBuilder();
+            results.append("Word Count: ").append(wordCount).append("\n");
+            results.append("Character Count: ").append(characterCount).append("\n");
+            results.append("Most Frequent Words:\n");
+            wordFrequencies.entrySet().stream()
+                    .sorted((e1, e2) -> e2.getValue().compareTo(e1.getValue()))
+                    .limit(10)
+                    .forEach(entry -> results.append(entry.getKey()).append(": ").append(entry.getValue()).append("\n"));
+            writer.write(results.toString());
+        } catch (IOException e) {
+            System.err.println("Error exporting results: " + e.getMessage());
+        }
+    }
+}
+```
+
+This optimized program uses `Files.readString(Paths.get(fileName))` for more efficient file reading, `\\W+` for correct word splitting, and `getOrDefault(word, 0) + 1` for simplified word frequency calculation. The export method is refactored to use `StringBuilder` for improved performance. The program also handles edge cases such as empty files, non-existent words in search, and proper file handling with try-with-resources.
