+            return new String(Files.readAllBytes(Paths.get(filePath)));
+        } catch(IOException e) {
+            System.err.println("Error reading file " + filePath + ": " + e.getMessage());
+            return "";
+        }
+    }
+
+    // Counts words by splitting on whitespace and returns the count.
+    private static int countWords(String content) {
+        if (content.trim().isEmpty()) return 0;
+        return content.split("\\s+").length;
+    }
+
+    // Counts characters excluding newline characters.
+    private static int countCharacters(String content) {
+        return content.replace("\n", "").length();
+    }
+
+    // Analyzes word frequencies in the text. The words are normalized to lowercase and punctuation is removed.
+    private static Map<String, Integer> wordFrequencies(String content) {
+        Map<String, Integer> freqMap = new HashMap<>();
+        // Remove punctuation and non-word characters; use whitespace split
+        String[] words = content.replaceAll("[^\\w\\s]", "").toLowerCase().split("\\s+");
+        for (String word : words) {
+            if(word.isEmpty()) continue;
+            freqMap.put(word, freqMap.getOrDefault(word, 0) + 1);
+        }
+        return freqMap;
+    }
+
+    // Returns a sorted list (descending by frequency) of the top N words.
+    private static List<Map.Entry<String, Integer>> getTopNWords(Map<String, Integer> freqMap, int topN) {
+        return freqMap.entrySet().stream()
+            .sorted(Map.Entry.comparingByValue(Comparator.reverseOrder()))
+            .limit(topN)
+            .collect(Collectors.toList());
+    }
+
+    // Search for a specific word in the text (case-insensitive) and returns the occurrence count and line numbers.
+    private static void searchWord(String filePath, String searchWord) {
+        int count = 0;
+        List<Integer> lineNumbers = new ArrayList<>();
+        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
+            String line;
+            int lineNo = 1;
+            while ((line = reader.readLine()) != null) {
+                // simple case-insensitive contains check after removing punctuation.
+                String cleanedLine = line.replaceAll("[^\\w\\s]", "").toLowerCase();
+                String[] words = cleanedLine.split("\\s+");
+                for (String w : words) {
+                    if (w.equals(searchWord.toLowerCase())) {
+                        count++;
+                        // record the line number if not already recorded for this line.
+                        if (!lineNumbers.contains(lineNo))
+                            lineNumbers.add(lineNo);
+                    }
+                }
+                lineNo++;
+            }
+        } catch (IOException e) {
+            System.err.println("Error searching word: " + e.getMessage());
+        }
+        System.out.println("Search Result for \"" + searchWord + "\":");
+        System.out.println("Total occurrences: " + count);
+        if (!lineNumbers.isEmpty())
+            System.out.println("Found in lines: " + lineNumbers);
+        else
+            System.out.println("Word not found in file.");
+    }
+
+    // Export analysis report as .txt or .csv.
+    private static void exportReport(String exportType, String reportContent) {
+        String fileName = (exportType.equalsIgnoreCase("csv")) ? "analysis_report.csv" : "analysis_report.txt";
+        try (BufferedWriter writer = new BufferedWriter(new FileWriter(fileName))) {
+            writer.write(reportContent);
+            System.out.println("Report exported as: " + fileName);
+        } catch (IOException e) {
+            System.err.println("Error exporting report: " + e.getMessage());
+        }
+    }
+
+    public static void main(String[] args) {
+        Scanner scanner = new Scanner(System.in);
+        // Create sample file if it doesn't exist.
+        createSampleFile();
+
+        System.out.println("Welcome to Java Text File Analyzer");
+        System.out.println("-----------------------------------");
+        // Use the current directory to find all .txt files.
+        File currentDir = new File(".");
+        File[] txtFiles = currentDir.listFiles((dir, name) -> name.toLowerCase().endsWith(".txt"));
+        
+        if (txtFiles == null || txtFiles.length == 0) {
+            System.out.println("No .txt files found in the current directory.");
+            scanner.close();
+            return;
+        }
+        System.out.println("Text files found in the current directory:");
+        for (int i = 0; i < txtFiles.length; i++) {
+            System.out.println((i + 1) + ". " + txtFiles[i].getName());
+        }
+        System.out.print("Select a file to analyze by entering its number: ");
+        int selection = scanner.nextInt();
+        scanner.nextLine(); // consume newline
+        if (selection < 1 || selection > txtFiles.length) {
+            System.out.println("Invalid selection.");
+            scanner.close();
+            return;
+        }
+        String fileName = txtFiles[selection - 1].getName();
+        String content = readFileContent(fileName);
+        if(content.isEmpty()){
+            System.out.println("File is empty or could not be read.");
+            scanner.close();
+            return;
+        }
+
+        // Perform basic analysis.
+        int wordCount = countWords(content);
+        int charCount = countCharacters(content);
+        Map<String, Integer> freqMap = wordFrequencies(content);
+
+        System.out.println("\nAnalysis Results for " + fileName + ":");
+        System.out.println("Total word count: " + wordCount);
+        System.out.println("Total character count (excluding newlines): " + charCount);
+
+        System.out.print("Enter the number of top frequent words to display: ");
+        int topN = scanner.nextInt();
+        scanner.nextLine(); // consume newline
+
+        List<Map.Entry<String, Integer>> topWords = getTopNWords(freqMap, topN);
+        System.out.println("Top " + topN + " most frequent words:");
+        for (Map.Entry<String, Integer> entry : topWords) {
+            System.out.println(entry.getKey() + ": " + entry.getValue());
+        }
+
+        // Search functionality
+        System.out.print("\nEnter a word to search in the file: ");
+        String searchWord = scanner.nextLine();
+        searchWord(fileName, searchWord);
+
+        // Prepare report content
+        StringBuilder reportBuilder = new StringBuilder();
+        reportBuilder.append("Text File Analysis Report for: ").append(fileName).append("\n");
+        reportBuilder.append("Total Words: ").append(wordCount).append("\n");
+        reportBuilder.append("Total Characters (excluding newlines): ").append(charCount).append("\n");
+        reportBuilder.append("Top ").append(topN).append(" Frequent Words:\n");
+        for (Map.Entry<String, Integer> entry : topWords) {
+            reportBuilder.append(entry.getKey()).append(": ").append(entry.getValue()).append("\n");
+        }
+        reportBuilder.append("Search Result for \"").append(searchWord).append("\":\n");
+        // For a simple report, we can repeat the search result summary.
+        // Here we re-calculate the count for simplicity.
+        int searchCount = freqMap.getOrDefault(searchWord.toLowerCase(), 0);
+        reportBuilder.append("Total Occurrences: ").append(searchCount).append("\n");
+
+        // Export results
+        System.out.print("\nWould you like to export the report? (y/n): ");
+        String exportChoice = scanner.nextLine();
+        if(exportChoice.equalsIgnoreCase("y")){
+            System.out.print("Enter export format (txt/csv): ");
+            String format = scanner.nextLine();
+            exportReport(format, reportBuilder.toString());
+        } else {
+            System.out.println("Report not exported.");
+        }
+        
+        System.out.println("Analysis complete.");
+        scanner.close();
+    }
+}
+```
+
+Explanation:
+1. The program first ensures that a sample file ("sample.txt") is created.
+2. It then lists all .txt files in the current directory for selection.
+3. After selecting a file, it calculates the total words and characters, and determines the frequency of each word.
+4. You can specify how many top frequent words to display.
+5. A search functionality lets you input a word to see how many times it occurs (and on which lines).
+6. Finally, the program asks if you want to export the analysis report as either .txt or .csv.
+
