+  const [selectedMetric, setSelectedMetric] = useState<'highSchool' | 'bachelors' | 'graduate'>('bachelors');
+
+  // Prepare data for ML model
+  const prepareTrainingData = useCallback((data: EducationData[]) => {
+    const regionData = data.filter(d => d.region === selectedRegion);
+    
+    const xs = tf.tensor2d(
+      regionData.map(d => [d.year]), 
+      [regionData.length, 1]
+    );
+    
+    const ys = tf.tensor2d(
+      regionData.map(d => [d[selectedMetric]]), 
+      [regionData.length, 1]
+    );
+
+    return { xs, ys };
+  }, [selectedRegion, selectedMetric]);
+
+  // Create and train ML model
+  const createAndTrainModel = useCallback(async (xs: tf.Tensor, ys: tf.Tensor) => {
+    // Dispose of existing model if it exists
+    if (predictionModel) {
+      predictionModel.dispose();
+    }
+
+    // Create a sequential model
+    const model = tf.sequential();
+    
+    // Add layers
+    model.add(tf.layers.dense({
+      units: 50, 
+      activation: 'relu', 
+      inputShape: [1]
+    }));
+    model.add(tf.layers.dense({
+      units: 20, 
+      activation: 'relu'
+    }));
+    model.add(tf.layers.dense({
+      units: 1
+    }));
+
+    // Compile the model
+    model.compile({
+      optimizer: tf.train.adam(0.1),
+      loss: 'meanSquaredError'
+    });
+
+    // Train the model
+    await model.fit(xs, ys, {
+      epochs: 250,
+      batchSize: 32
+    });
+
+    return model;
+  }, []);
+
+  // Generate predictions
+  const generatePredictions = useCallback(async (model: tf.Sequential) => {
+    const futureyears = [2021, 2022, 2023, 2024, 2025];
+    
+    const predictionTensors = futureyears.map(year => 
+      model.predict(tf.tensor2d([[year]], [1, 1])) as tf.Tensor
+    );
+
+    const predictions = await Promise.all(
+      predictionTensors.map(async (tensor) => {
+        const value = await tensor.data();
+        tensor.dispose();
+        return Math.max(0, Math.min(100, value[0])); // Clamp between 0-100
+      })
+    );
+
+    return predictions;
+  }, []);
+
+  // Initialize and train model on component mount
