+      setHistoricalData(data);
+
+      // Prepare training data
+      const { xs, ys } = prepareTrainingData(data);
+
+      // Create and train model
+      const model = await createAndTrainModel(xs, ys);
+      setPredictionModel(model);
+
+      // Generate predictions
+      const predictionResults = await generatePredictions(model);
+      setPredictions(predictionResults);
+
+      // Clean up tensors
+      xs.dispose();
+      ys.dispose();
+    };
+
+    initializeModel();
+  }, [selectedRegion, selectedMetric]);
+
+  // Prepare chart data
+  const chartData = {
+    labels: historicalData
+      .filter(d => d.region === selectedRegion)
+      .map(d => d.year)
