+    datasets: [
+      {
+        label: 'Historical Data',
+        data: historicalData
+          .filter(d => d.region === selectedRegion)
+          .map(d => d[selectedMetric]),
+        borderColor: 'blue',
+        backgroundColor: 'rgba(0, 0, 255, 0.1)',
+      },
+      {
+        label: 'Predicted Trend',
+        data: [
+          ...historicalData
+            .filter(d => d.region === selectedRegion)
+            .map(d => d[selectedMetric]),
+          ...predictions
+        ],
+        borderColor: 'red',
+        backgroundColor: 'rgba(255, 0, 0, 0.1)',
+        borderDash: [5, 5]
+      }
+    ]
+  };
+
+  return (
+    <div className="container mx-auto p-6 bg-gray-100">
+      <h1 className="text-3xl font-bold text-center mb-6">
+        Educational Attainment Trend Predictor
+      </h1>
+
+      {/* Filters */}
+      <div className="flex justify-center space-x-4 mb-6">
+        <select 
+          value={selectedRegion}
+          onChange={(e) => setSelectedRegion(e.target.value)}
+          className="p-2 border rounded"
+        >
+          {['Northeast', 'Midwest', 'South', 'West'].map(region => (
+            <option key={region} value={region}>{region}</option>
+          ))}
+        </select>
+
+        <select 
+          value={selectedMetric}
+          onChange={(e) => setSelectedMetric(e.target.value as any)}
+          className="p-2 border rounded"
+        >
+          <option value="highSchool">High School</option>
+          <option value="bachelors">Bachelors</option>
+          <option value="graduate">Graduate</option>
+        </select>
+      </div>
+
+      {/* Prediction Visualization */}
+      <div className="bg-white p-6 rounded-lg shadow-md">
+        <Line 
+          data={chartData}
+          options={{
+            responsive: true,
+            plugins: {
+              title: {
+                display: true,
+                text: `${selectedRegion} - ${selectedMetric.charAt(0).toUpperCase() + selectedMetric.slice(1)} Degree Trend`
+              }
+            }
+          }}
+        />
+      </div>
+
+      {/* Prediction Details */}
+      <div className="mt-6 text-center">
+        <h2 className="text-xl font-semibold mb-4">Future Predictions</h2>
+        <div className="flex justify-center space-x-4">
+          {[2021, 2022, 2023, 2024, 2025].map((year, index) => (
+            <div key={year} className="bg-blue-100 p-4 rounded">
+              <p className="font-bold">{year}</p>
+              <p>{predictions[index]?.toFixed(2) || 'Loading...'}</p>
+            </div>
+          ))}
+        </div>
+      </div>
+    </div>
+  );
+};
+
+export default EducationTrendPredictor;
