+  useEffect(() => {
+    if (joined) {
+      const ws = new WebSocket("ws://localhost:8080"); // Adjust for your server
+      wsRef.current = ws;
+
+      ws.onopen = () => {
+        setStatusMessage("Connected to server");
+        // Send a "join" message so the server recognizes this user
+        ws.send(JSON.stringify({ type: "join", username }));
+      };
+
+      ws.onmessage = (event) => {
+        try {
+          const data = JSON.parse(event.data);
+          switch (data.type) {
+            case "joined":
+              setGameMessage(`Player "${data.username}" joined the game`);
+              break;
+            case "left":
+              setGameMessage(`Player "${data.username}" left the game`);
+              break;
